import { NextResponse } from "next/server";
import { getToken } from "next-auth/jwt";
import { getServerSession } from "next-auth";
import { Types } from "mongoose";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { BuyingRequest, AuditEvent } from "@/models";

function isAdminToken(token: { id?: string; role?: string } | null) {
  if (!token) return false;
  return token.id === "admin" || token.role === "Super Admin";
}

export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    if (!Types.ObjectId.isValid(id)) {
      return NextResponse.json({ error: "Invalid buying request ID" }, { status: 400 });
    }

    let token = await getToken({ req: request as Parameters<typeof getToken>[0]["req"], secret: process.env.NEXTAUTH_SECRET });
    if (!token) {
      const session = await getServerSession(authOptions).catch(() => null);
      if (session?.user) {
        token = { id: session.user.id, role: session.user.role } as any;
      }
    }
    if (!token || !isAdminToken(token)) {
      return NextResponse.json(
        { error: "Admin access required. Only administrators can approve buying requests." },
        { status: 403 },
      );
    }

    await connectToDatabase();

    const existingReq = await BuyingRequest.findById(id);
    if (!existingReq) {
      return NextResponse.json({ error: "Buying request not found" }, { status: 404 });
    }

    const currentAdminStatus = (existingReq as unknown as { adminStatus?: string }).adminStatus;
    const isAlreadyApproved = currentAdminStatus === "Approved" || existingReq.status === "Approved";
    if (isAlreadyApproved) {
      return NextResponse.json(
        { error: "This buying request has already been approved." },
        { status: 409 },
      );
    }

    await BuyingRequest.findByIdAndUpdate(id, {
      $set: {
        adminStatus: "Approved",
        status: "Approved",
      },
    });

    // Record audit event
    try {
      await AuditEvent.create({
        organizationId: existingReq.organizationId,
        actorId: String(token.id),
        action: "buying_request.admin_approved",
        entityType: "BuyingRequest",
        entityId: id,
        changes: {
          adminStatus: "Approved",
          status: "Approved",
          previousStatus: existingReq.status || "Pending",
        },
        occurredAt: new Date(),
      });
    } catch (auditErr) {
      console.error("Failed to record admin approval audit:", auditErr);
    }

    return NextResponse.json({
      ok: true,
      message: `Buying request ${(existingReq as unknown as { requestId: string }).requestId} has been approved successfully.`,
    });
  } catch (error) {
    console.error("POST /api/admin/buying-requests/[id]/approve error:", error);
    return NextResponse.json({ error: "Failed to approve buying request" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getToken } from "next-auth/jwt";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { BuyingRequest, Organization } from "@/models";

function isAdminToken(token: { id?: string; role?: string } | null) {
  if (!token) return false;
  return token.id === "admin" || token.role === "Super Admin";
}

export async function GET(request: Request) {
  try {
    let token = await getToken({ req: request as Parameters<typeof getToken>[0]["req"], secret: process.env.NEXTAUTH_SECRET });
    if (!token) {
      const session = await getServerSession(authOptions).catch(() => null);
      if (session?.user) {
        token = { id: session.user.id, role: session.user.role } as any;
      }
    }
    if (!token || !isAdminToken(token)) {
      return NextResponse.json({ error: "Admin access required" }, { status: 403 });
    }

    await connectToDatabase();

    const url = new URL(request.url);
    const adminStatus = url.searchParams.get("adminStatus") || "Pending";
    const page = Math.max(1, Number(url.searchParams.get("page") ?? 1) || 1);
    const limit = Math.min(100, Math.max(1, Number(url.searchParams.get("limit") ?? 20) || 20));

    const filter: Record<string, unknown> = {};
    if (adminStatus === "Pending") {
      filter.$or = [
        { adminStatus: "Pending" },
        { status: "Pending" },
        { adminStatus: { $exists: false }, status: { $ne: "Approved" } },
      ];
    } else if (adminStatus === "Approved") {
      filter.$or = [
        { adminStatus: "Approved" },
        { status: "Approved" },
      ];
    } else if (adminStatus !== "all") {
      filter.adminStatus = adminStatus;
    }

    const [requests, total] = await Promise.all([
      BuyingRequest.find(filter)
        .sort({ createdAt: -1 })
        .skip((page - 1) * limit)
        .limit(limit)
        .lean(),
      BuyingRequest.countDocuments(filter),
    ]);

    // Fetch org names
    const orgIds = [...new Set(requests.map((r) => String(r.organizationId)))];
    const orgs = await Organization.find({ _id: { $in: orgIds } })
      .select("_id name tradeName")
      .lean();
    const orgMap = new Map(orgs.map((o) => [String(o._id), ((o as any).tradeName || o.name) as string]));

    const formatted = requests.map((r) => ({
      id: String(r._id),
      requestId: r.requestId,
      organizationId: String(r.organizationId),
      organizationName: orgMap.get(String(r.organizationId)) || "Unknown",
      commodity: r.commodity,
      requiredQuantity: r.requiredQuantity,
      unit: r.unit,
      targetPrice: r.targetPrice ?? null,
      deliveryLocation: r.deliveryLocation,
      requiredDeliveryDate: r.requiredDeliveryDate,
      buyerName: r.buyerName,
      buyerCompany: r.buyerCompany,
      status: r.status || "Pending",
      adminStatus: (r as any).adminStatus || (r.status === "Approved" ? "Approved" : "Pending"),
      offersCount: r.offersCount ?? 0,
      createdAt: r.createdAt,
    }));

    return NextResponse.json({
      requests: formatted,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
    });
  } catch (error) {
    console.error("GET /api/admin/buying-requests error:", error);
    return NextResponse.json({ error: "Failed to load buying requests" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { Types } from "mongoose";
import { getBuyingScope, seedInitialRequestsIfEmpty, recordBuyingAudit } from "@/lib/buying-access";
import { BuyingRequest, RequestOffer } from "@/models";

const buyingRequestCreateSchema = z.object({
  commodity: z.string().trim().min(2, "Commodity name is required").max(100),
  requiredQuantity: z.coerce.number().positive("Quantity must be greater than 0"),
  unit: z.string().trim().min(1).default("MT"),
  targetPrice: z.union([z.coerce.number().positive(), z.null()]).optional(),
  qualitySpecs: z.string().trim().max(1000).optional(),
  deliveryLocation: z.string().trim().min(2, "Delivery location is required").max(200),
  requiredDeliveryDate: z.string().refine((val) => !isNaN(Date.parse(val)), "Valid delivery date is required"),
  description: z.string().trim().max(2000).optional(),
  buyerCompany: z.string().trim().max(160).optional(),
  buyerPhone: z.string().trim().max(30).optional(),
});

export async function GET(request: Request) {
  try {
    const url = new URL(request.url);
    const requestedOrgId = url.searchParams.get("organizationId") || undefined;
    const scopeResult = await getBuyingScope(requestedOrgId, "view-buying-requests", { req: request });
    if ("response" in scopeResult) return scopeResult.response;
    const { organizationId, actorId, name, email, isAdmin, role } = scopeResult.scope;

    // Seed sample requests if empty
    await seedInitialRequestsIfEmpty(organizationId, actorId, name, email);

    // Existing data: set requests without a status to Pending without overwriting approved ones
    const missingStatusFilter: Record<string, unknown> = {
      organizationId: new Types.ObjectId(organizationId),
      $or: [{ status: { $exists: false } }, { status: null }, { status: "" }],
    };
    await BuyingRequest.updateMany(
      missingStatusFilter,
      { $set: { status: "Pending", adminStatus: "Pending" } },
    );

    const page = Math.max(1, Number(url.searchParams.get("page") ?? 1) || 1);
    const limit = Math.min(100, Math.max(1, Number(url.searchParams.get("limit") ?? 12) || 12));
    const search = (url.searchParams.get("search") ?? "").trim().slice(0, 100);
    const commodity = (url.searchParams.get("commodity") ?? "").trim();
    const status = (url.searchParams.get("status") ?? "").trim();
    const view = (url.searchParams.get("view") ?? "all").trim(); // 'all', 'my-requests', 'open-market', 'my-offers'

    const orgObjectId = new Types.ObjectId(organizationId);
    const userObjectId = Types.ObjectId.isValid(actorId) ? new Types.ObjectId(actorId) : null;

    const filter: Record<string, unknown> = {
      organizationId: orgObjectId,
    };

    // Role or view based filtering
    if (view === "my-requests" && userObjectId) {
      filter.buyerId = userObjectId;
    } else if (view === "open-market") {
      // Marketplace for sellers: requests that are Approved, Open, or Offers Received
      filter.status = { $in: ["Approved", "Open", "Offers Received"] };
    } else if (view === "my-offers" && userObjectId) {
      // Requests where the current user has submitted an offer
      const myOffers = await RequestOffer.find({ sellerId: userObjectId }).select("requestId").lean();
      const reqIds = myOffers.map((o) => o.requestId);
      filter._id = { $in: reqIds };
    } else if (role === "Buyer" && userObjectId && view !== "open-market") {
      // Default view for Buyer role if not browsing open market
      filter.buyerId = userObjectId;
    }

    if (search) {
      const escaped = search.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      filter.$or = [
        { requestId: { $regex: escaped, $options: "i" } },
        { commodity: { $regex: escaped, $options: "i" } },
        { deliveryLocation: { $regex: escaped, $options: "i" } },
        { buyerCompany: { $regex: escaped, $options: "i" } },
        { buyerName: { $regex: escaped, $options: "i" } },
      ];
    }

    if (commodity && commodity !== "all") {
      filter.commodity = { $regex: new RegExp(`^${commodity.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`, "i") };
    }

    if (status && status !== "all") {
      if (status === "In Progress") {
        filter.status = { $in: ["In Progress", "Offers Received", "Accepted"] };
      } else if (status === "Closed") {
        filter.status = { $in: ["Closed", "Fulfilled", "Cancelled", "Rejected"] };
      } else if (status === "Pending") {
        filter.$or = [{ status: "Pending" }, { adminStatus: "Pending" }];
      } else if (status === "Approved") {
        filter.$or = [{ status: "Approved" }, { adminStatus: "Approved" }];
      } else {
        filter.status = status;
      }
    }

    const [requests, total, allCommoditiesAgg] = await Promise.all([
      BuyingRequest.find(filter)
        .sort({ createdAt: -1 })
        .skip((page - 1) * limit)
        .limit(limit)
        .lean(),
      BuyingRequest.countDocuments(filter),
      BuyingRequest.distinct("commodity", { organizationId: orgObjectId }),
    ]);

    // Find if user submitted offers for these requests
    const requestIds = requests.map((r) => r._id);
    const userOffers = userObjectId
      ? await RequestOffer.find({
          requestId: { $in: requestIds },
          sellerId: userObjectId,
        }).lean()
      : [];

    const offerMap = new Map(
      userOffers.map((o) => [
        String(o.requestId),
        {
          id: String(o._id),
          offerId: o.offerId,
          offeredPrice: o.offeredPrice,
          availableQuantity: o.availableQuantity,
          deliveryTerms: o.deliveryTerms,
          status: o.status,
          createdAt: o.createdAt,
        },
      ]),
    );

    const formattedRequests = requests.map((r) => {
      const isMine = userObjectId ? String(r.buyerId) === String(userObjectId) : false;
      return {
        id: String(r._id),
        requestId: r.requestId,
        commodity: r.commodity,
        requiredQuantity: r.requiredQuantity,
        unit: r.unit,
        targetPrice: r.targetPrice ?? null,
        qualitySpecs: r.qualitySpecs || "",
        deliveryLocation: r.deliveryLocation,
        requiredDeliveryDate: r.requiredDeliveryDate,
        description: r.description || "",
        status: r.status || "Pending",
        adminStatus: (r as any).adminStatus || (r.status === "Approved" ? "Approved" : "Pending"),
        offersCount: r.offersCount ?? 0,
        acceptedOfferId: r.acceptedOfferId ? String(r.acceptedOfferId) : null,
        buyerId: String(r.buyerId),
        buyerName: r.buyerName,
        buyerCompany: r.buyerCompany,
        buyerEmail: r.buyerEmail || "",
        buyerPhone: r.buyerPhone || "",
        isMine,
        myOffer: offerMap.get(String(r._id)) || null,
        createdAt: r.createdAt,
        updatedAt: r.updatedAt,
      };
    });

    return NextResponse.json({
      requests: formattedRequests,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
      availableCommodities: (allCommoditiesAgg as string[]).sort(),
      currentUser: {
        id: actorId,
        name,
        email,
        role,
        isAdmin,
      },
    });
  } catch (error) {
    console.error("GET /api/buying-requests error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to load buying requests" },
      { status: 500 },
    );
  }
}

export async function POST(request: Request) {
  try {
    let payload: unknown;
    try {
      payload = await request.json();
    } catch {
      return NextResponse.json({ error: "Invalid JSON request body" }, { status: 400 });
    }

    const parsed = buyingRequestCreateSchema.safeParse(payload);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "Validation failed", issues: parsed.error.issues },
        { status: 400 },
      );
    }

    const requestedOrgId =
      typeof payload === "object" && payload !== null && "organizationId" in payload
        ? String(payload.organizationId)
        : undefined;

    const scopeResult = await getBuyingScope(requestedOrgId, "manage-buying-requests", { req: request });
    if ("response" in scopeResult) return scopeResult.response;
    const { organizationId, actorId, name, email } = scopeResult.scope;

    const orgObjectId = new Types.ObjectId(organizationId);
    const userObjectId = Types.ObjectId.isValid(actorId)
      ? new Types.ObjectId(actorId)
      : new Types.ObjectId("6ad5bbebc705e44f38b65451");

    // Generate unique sequential request ID
    let nextNum = 2001;
    const existingReqs = await BuyingRequest.find({ organizationId: orgObjectId })
      .select("requestId")
      .lean();
    const existingIds = new Set(existingReqs.map((r) => r.requestId));
    while (existingIds.has(`BR-${nextNum}`)) {
      nextNum++;
    }
    const requestId = `BR-${nextNum}`;

    const newRequest = await BuyingRequest.create({
      requestId,
      organizationId: orgObjectId,
      buyerId: userObjectId,
      buyerName: name || "Buyer",
      buyerCompany: parsed.data.buyerCompany || name || "BharatGodam Trading",
      buyerEmail: email || undefined,
      buyerPhone: parsed.data.buyerPhone || undefined,
      commodity: parsed.data.commodity,
      requiredQuantity: parsed.data.requiredQuantity,
      unit: parsed.data.unit || "MT",
      targetPrice: parsed.data.targetPrice ?? null,
      qualitySpecs: parsed.data.qualitySpecs || undefined,
      deliveryLocation: parsed.data.deliveryLocation,
      requiredDeliveryDate: new Date(parsed.data.requiredDeliveryDate),
      description: parsed.data.description || undefined,
      status: "Pending",
      adminStatus: "Pending",
      offersCount: 0,
    });

    await recordBuyingAudit({
      organizationId,
      actorId,
      action: "buying_request.created",
      entityType: "BuyingRequest",
      entityId: String(newRequest._id),
      changes: {
        requestId,
        commodity: parsed.data.commodity,
        requiredQuantity: parsed.data.requiredQuantity,
        unit: parsed.data.unit,
        status: "Pending",
      },
    });

    return NextResponse.json(
      {
        ok: true,
        id: String(newRequest._id),
        requestId: newRequest.requestId,
        message: "Buying request published successfully",
      },
      { status: 201 },
    );
  } catch (error) {
    console.error("POST /api/buying-requests error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to create buying request" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { Expense } from "@/models";
import { expenseInputSchema, defaultDemoExpenses } from "../route";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    await connectToDatabase().catch(() => null);
    const expense = await Expense.findById(id).lean().catch(() => null);
    if (!expense) {
      const demo = defaultDemoExpenses.find((e) => e.id === id || e.referenceNumber === id);
      if (demo) {
        return NextResponse.json({ expense: demo });
      }
      return NextResponse.json({ error: "Expense not found" }, { status: 404 });
    }
    return NextResponse.json({ expense });
  } catch (err: unknown) {
    console.error("GET /api/expenses/[id] error:", err);
    return NextResponse.json({ error: "Failed to fetch expense" }, { status: 500 });
  }
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json({ error: "Invalid JSON payload" }, { status: 400 });
    }

    const parseResult = expenseInputSchema.safeParse(body);
    if (!parseResult.success) {
      return NextResponse.json(
        { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
        { status: 400 },
      );
    }

    const data = parseResult.data;
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    const expense = await Expense.findById(id).catch(() => null);
    if (!expense) {
      if (id.startsWith("EXP-") || id.startsWith("MIL-") || id.startsWith("demo-")) {
        return NextResponse.json({
          message: "Expense updated successfully",
          expense: { ...data, id, _id: id, referenceNumber: id },
        });
      }
      return NextResponse.json({ error: "Expense not found" }, { status: 404 });
    }

    let computedAmount = 0;
    if (data.expenseType === "mileage" && data.mileageDetails) {
      computedAmount = Math.round(data.mileageDetails.distance * data.mileageDetails.rate * 100) / 100;
      if (typeof data.amount === "number" && data.amount > 0) {
        computedAmount = data.amount;
      }
    } else if (data.items.length > 0) {
      computedAmount = data.items.reduce((sum, row) => sum + row.amount, 0);
    } else if (typeof data.amount === "number") {
      computedAmount = data.amount;
    }

    Object.assign(expense, {
      date: data.date,
      paidThrough: data.paidThrough,
      currency: data.currency,
      vendor: data.vendor,
      invoiceNumber: data.invoiceNumber,
      customerName: data.customerName,
      notes: data.notes,
      amount: computedAmount,
      status: data.status,
      billable: data.billable,
      project: data.project,
      reportingTags: data.reportingTags,
      items: data.items,
      mileageDetails: data.mileageDetails || null,
      receipts: data.receipts,
    });

    await expense.save();

    return NextResponse.json({
      message: "Expense updated successfully",
      expense,
    });
  } catch (err: unknown) {
    console.error("PUT /api/expenses/[id] error:", err);
    return NextResponse.json({ error: "Failed to update expense" }, { status: 500 });
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    await connectToDatabase().catch(() => null);
    const expense = await Expense.findByIdAndDelete(id).catch(() => null);
    if (!expense) {
      if (id.startsWith("EXP-") || id.startsWith("MIL-") || id.startsWith("demo-")) {
        return NextResponse.json({ message: "Expense deleted successfully" });
      }
      return NextResponse.json({ error: "Expense not found" }, { status: 404 });
    }
    return NextResponse.json({ message: "Expense deleted successfully" });
  } catch (err: unknown) {
    console.error("DELETE /api/expenses/[id] error:", err);
    return NextResponse.json({ error: "Failed to delete expense" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { z } from "zod";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { Item, ItemPreference, Organization, PurchaseBill, SalesDocument } from "@/models";
import { items as fallbackDemoItems } from "@/lib/demo-data";

const itemInputSchema = z.object({
  name: z.string().trim().min(1, "Name is required").max(120),
  type: z.enum(["goods", "service"]).default("goods"),
  unit: z.string().trim().default("pcs"),
  sku: z.string().trim().optional(),
  hsnCode: z.string().trim().optional(),
  trackSales: z.boolean().default(true),
  salesPrice: z.coerce.number().min(0).default(0),
  salesAccount: z.string().trim().default("Sales"),
  salesDescription: z.string().trim().default(""),
  trackPurchase: z.boolean().default(true),
  purchasePrice: z.coerce.number().min(0).default(0),
  purchaseAccount: z.string().trim().default("Cost of Goods Sold"),
  purchaseDescription: z.string().trim().default(""),
  preferredVendor: z.string().trim().default(""),
  openingStock: z.coerce.number().min(0).default(0),
});

export async function GET() {
  try {
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean();
      if (defaultOrg) {
        orgId = String(defaultOrg._id);
      }
    }

    const pref = orgId
      ? await ItemPreference.findOne({ organizationId: orgId }).lean().catch(() => null)
      : null;
    const inventoryEnabled = Boolean(pref?.inventoryEnabled);

    const query = orgId ? { organizationId: orgId, active: true } : { active: true };
    const dbItems = await Item.find(query).sort({ createdAt: -1 }).lean().catch(() => []);

    if (!dbItems || dbItems.length === 0) {
      return NextResponse.json({
        inventoryEnabled,
        items: fallbackDemoItems.map((item, idx) => ({
          id: `demo-${idx + 1}`,
          name: item.name,
          sku: item.sku,
          type: item.unit.toLowerCase().includes("service") ? "service" : "goods",
          unit: item.unit,
          salesPrice: item.rate,
          purchasePrice: Math.round(item.rate * 0.7),
          salesAccount: "Sales",
          purchaseAccount: "Cost of Goods Sold",
          salesDescription: `${item.name} for standard billing`,
          purchaseDescription: `${item.name} procurement`,
          preferredVendor: "Mohan Traders",
          stock: inventoryEnabled ? item.stock : 0,
          inventoryTracking: inventoryEnabled,
          active: true,
        })),
      });
    }

    // When inventory is enabled, calculate stock from opening stock + purchases - sales transactions
    const purchasesMap = new Map<string, number>();
    const salesMap = new Map<string, number>();

    if (inventoryEnabled) {
      try {
        const [purchaseBills, salesInvoices] = await Promise.all([
          PurchaseBill.find({
            ...(orgId ? { organizationId: orgId } : {}),
            status: { $ne: "Void" },
          })
            .select("items")
            .lean()
            .catch(() => []),
          SalesDocument.find({
            ...(orgId ? { organizationId: orgId } : {}),
            type: "Invoice",
            status: { $nin: ["Draft", "Cancelled", "Void"] },
          })
            .select("items")
            .lean()
            .catch(() => []),
        ]);

        for (const bill of purchaseBills) {
          for (const it of (bill as { items?: { itemId?: unknown; name?: string; quantity?: number }[] }).items || []) {
            const qty = Number(it.quantity) || 0;
            if (it.itemId) purchasesMap.set(String(it.itemId), (purchasesMap.get(String(it.itemId)) || 0) + qty);
            if (it.name) purchasesMap.set(it.name.toLowerCase().trim(), (purchasesMap.get(it.name.toLowerCase().trim()) || 0) + qty);
          }
        }

        for (const doc of salesInvoices) {
          for (const it of (doc as { items?: { itemId?: unknown; name?: string; quantity?: number }[] }).items || []) {
            const qty = Number(it.quantity) || 0;
            if (it.itemId) salesMap.set(String(it.itemId), (salesMap.get(String(it.itemId)) || 0) + qty);
            if (it.name) salesMap.set(it.name.toLowerCase().trim(), (salesMap.get(it.name.toLowerCase().trim()) || 0) + qty);
          }
        }
      } catch (calcErr) {
        console.error("Error calculating inventory stock levels:", calcErr);
      }
    }

    return NextResponse.json({
      inventoryEnabled,
      items: dbItems.map((item: any) => {
        let stock = 0;
        if (inventoryEnabled) {
          const itemIdStr = String(item._id);
          const itemNameKey = String(item.name || "").toLowerCase().trim();
          const purchased = purchasesMap.get(itemIdStr) ?? purchasesMap.get(itemNameKey) ?? 0;
          const sold = salesMap.get(itemIdStr) ?? salesMap.get(itemNameKey) ?? 0;
          const opening = Number(item.openingStock) || 0;
          stock = Math.max(0, opening + purchased - sold);
        }

        return {
          id: String(item._id),
          name: item.name,
          sku: item.sku,
          type: item.type ?? "goods",
          unit: item.unit ?? "pcs",
          salesPrice: item.salesPrice ?? 0,
          purchasePrice: item.purchasePrice ?? 0,
          salesAccount: item.salesAccount ?? "Sales",
          purchaseAccount: item.purchaseAccount ?? "Cost of Goods Sold",
          salesDescription: item.salesDescription ?? "",
          purchaseDescription: item.purchaseDescription ?? "",
          preferredVendor: item.preferredVendor ?? "",
          stock,
          inventoryTracking: inventoryEnabled,
          active: item.active ?? true,
        };
      }),
    });
  } catch (err) {
    console.error("GET /api/items error:", err);
    return NextResponse.json(
      {
        items: fallbackDemoItems.map((item, idx) => ({
          id: `demo-${idx + 1}`,
          name: item.name,
          sku: item.sku,
          type: item.unit.toLowerCase().includes("service") ? "service" : "goods",
          unit: item.unit,
          salesPrice: item.rate,
          purchasePrice: Math.round(item.rate * 0.7),
          stock: item.stock,
          active: true,
        })),
      },
      { status: 200 },
    );
  }
}

export async function POST(request: Request) {
  try {
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json({ error: "Invalid JSON payload" }, { status: 400 });
    }

    const parseResult = itemInputSchema.safeParse(body);
    if (!parseResult.success) {
      return NextResponse.json(
        { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
        { status: 400 },
      );
    }

    const data = parseResult.data;
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase();

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean();
      if (!defaultOrg) {
        return NextResponse.json({ error: "No active organization found" }, { status: 400 });
      }
      orgId = String(defaultOrg._id);
    }

    const pref = orgId
      ? await ItemPreference.findOne({ organizationId: orgId }).lean().catch(() => null)
      : null;
    const inventoryEnabled = Boolean(pref?.inventoryEnabled);

    const sku =
      data.sku?.trim() ||
      `SKU-${data.name.replace(/[^a-zA-Z0-9]/g, "").slice(0, 4).toUpperCase()}-${Math.floor(1000 + Math.random() * 9000)}`;

    const newItem = await Item.create({
      organizationId: orgId,
      name: data.name,
      sku,
      hsnCode: data.hsnCode || undefined,
      type: data.type,
      unit: data.unit,
      salesPrice: data.salesPrice,
      purchasePrice: data.purchasePrice,
      salesAccount: data.salesAccount,
      salesDescription: data.salesDescription,
      purchaseAccount: data.purchaseAccount,
      purchaseDescription: data.purchaseDescription,
      preferredVendor: data.preferredVendor,
      trackSales: data.trackSales,
      trackPurchase: data.trackPurchase,
      inventoryTracking: inventoryEnabled,
      openingStock: inventoryEnabled ? data.openingStock : 0,
      active: true,
    });

    return NextResponse.json(
      {
        message: "Item created successfully",
        item: {
          id: String(newItem._id),
          name: newItem.name,
          sku: newItem.sku,
          type: newItem.type,
          unit: newItem.unit,
          salesPrice: newItem.salesPrice,
          purchasePrice: newItem.purchasePrice,
          salesAccount: newItem.salesAccount,
          purchaseAccount: newItem.purchaseAccount,
          preferredVendor: newItem.preferredVendor,
          stock: newItem.openingStock,
          active: newItem.active,
        },
      },
      { status: 201 },
    );
  } catch (err: unknown) {
    console.error("POST /api/items error:", err);
    const message = err instanceof Error ? err.message : "Internal server error";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

