        updatedAt: bill.updatedAt ? new Date(bill.updatedAt).toISOString() : "",
      },
    });
  } catch (error) {
    console.error("GET /api/purchases/bills/[id] error:", error);
    return respondError("Failed to fetch bill details.", 500);
  }
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    if (!id || !isValidObjectId(id)) {
      return respondError("Invalid bill ID.", 400);
    }

    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return respondError("Sign in to edit bill.", 401);
    }

    let payload: any;
    try {
      payload = await request.json();
    } catch {
      return respondError("Submit valid JSON data.", 400);
    }

    let organizationId = session.user.organizationId;
    if (session.user.id === "admin" && payload.organizationId && isValidObjectId(payload.organizationId)) {
      organizationId = payload.organizationId;
    }

    await connectToDatabase();
    const orgObjId = new Types.ObjectId(organizationId);

    const bill = await PurchaseBill.findOne({
      _id: new Types.ObjectId(id),
      organizationId: orgObjId,
    });

    if (!bill) {
      return respondError("Bill not found.", 404);
    }

    const {
      vendorId,
      billNumber: customBillNumber,
      orderNumber,
      billDate,
      dueDate: customDueDate,
      paymentTerms,
      accountsPayable,
      subject,
      items,
      discount,
      discountType,
      taxType,
      taxRate,
      adjustment,
      notes,
      termsAndConditions,
      attachments,
      status: requestedStatus,
    } = payload;

    if (vendorId && isValidObjectId(vendorId)) {
      bill.vendorId = new Types.ObjectId(vendorId);
      const vend = await Vendor.findOne({ _id: bill.vendorId, organizationId: orgObjId }).select("name");
      if (vend && vend.name) bill.vendorName = String(vend.name);
    }

    if (customBillNumber && customBillNumber.trim()) {
      const trimmed = customBillNumber.trim();
      if (trimmed !== bill.billNumber) {
        const existing = await PurchaseBill.findOne({
          _id: { $ne: bill._id },
          organizationId: orgObjId,
          billNumber: { $regex: new RegExp(`^${trimmed}$`, "i") },
        });
        if (existing) {
          return respondError(`Bill number "${trimmed}" is already used by another bill.`, 409);
        }
        bill.billNumber = trimmed;
      }
    }

    if (orderNumber !== undefined) bill.orderNumber = orderNumber.trim();
    if (subject !== undefined) bill.subject = subject.trim();
    if (paymentTerms !== undefined) bill.paymentTerms = paymentTerms;
    if (accountsPayable !== undefined) bill.accountsPayable = accountsPayable;
    if (notes !== undefined) bill.notes = notes.trim();
    if (termsAndConditions !== undefined) bill.termsAndConditions = termsAndConditions.trim();

    if (billDate) {
      bill.billDate = new Date(billDate);
    }

    if (customDueDate) {
      bill.dueDate = new Date(customDueDate);
    } else if (bill.billDate && bill.paymentTerms) {
      const calcStr = calculateDueDate(
        bill.billDate.toISOString().split("T")[0],
        bill.paymentTerms,
      );
      if (calcStr) bill.dueDate = new Date(calcStr);
    }

    // If items provided, recalculate totals
    if (Array.isArray(items) && items.length > 0) {
      const calcOutput = calculateBillTotals({
        items: items.map((it: any) => ({
          itemId: it.itemId,
          name: (it.name || "").trim() || "Item",
          description: (it.description || "").trim(),
          account: it.account || "Cost of Goods Sold",
          quantity: Math.max(0, Number(it.quantity) || 1),
          rate: Math.max(0, Number(it.rate) || 0),
          taxRate: Number(it.taxRate) || 0,
          customerId: it.customerId,
          customerName: it.customerName || "",
          amount: Math.round((Number(it.quantity || 1) * Number(it.rate || 0)) * 100) / 100,
        })),
        discount: Number(discount) || 0,
        discountType: discountType === "amount" ? "amount" : "percent",
        taxType: taxType || bill.taxType || "GST",
        taxRate: Number(taxRate) || 0,
        adjustment: Number(adjustment) || 0,
      });

      bill.items = calcOutput.items as any;
      bill.subTotal = calcOutput.subTotal;
      bill.discount = Number(discount) || 0;
      bill.discountType = discountType || "percent";
      bill.discountAmount = calcOutput.discountAmount;
      bill.taxType = taxType || "GST";
      bill.taxRate = Number(taxRate) || 0;
      bill.taxAmount = calcOutput.taxAmount;
      bill.cgst = calcOutput.cgst;
      bill.sgst = calcOutput.sgst;
      bill.igst = calcOutput.igst;
      bill.adjustment = calcOutput.adjustment;
      bill.total = calcOutput.total;

      // Recalculate status based on amountPaid and vendorCreditApplied
      const currentPaid = Number(bill.amountPaid || 0);
      const currentCredit = Number(bill.vendorCreditApplied || 0);
      const remainingDue = Math.max(0, Math.round((bill.total - currentCredit - currentPaid) * 100) / 100);
      if (remainingDue === 0 && bill.total > 0) {
        bill.status = "Paid";
      } else if (currentPaid > 0 || currentCredit > 0) {
        bill.status = "Partially Paid";
      } else if (requestedStatus) {
        bill.status = requestedStatus;
      }
    } else if (requestedStatus) {
      bill.status = requestedStatus;
    }

    // Attachments
    if (Array.isArray(attachments)) {
      if (attachments.length > 5) {
        return respondError("A maximum of 5 attachments is allowed per bill.", 400);
      }
      for (const att of attachments) {
        if (att.size && att.size > 10 * 1024 * 1024) {
          return respondError(`File "${att.name}" exceeds the maximum allowed size of 10 MB.`, 400);
        }
      }
      bill.attachments = attachments.map((att: any) => ({
        name: att.name || "attachment",
        size: Number(att.size) || 0,
        type: att.type || "",
        dataUrl: att.dataUrl || "",
        uploadedAt: att.uploadedAt ? new Date(att.uploadedAt) : new Date(),
      })) as any;
    }

    await bill.save();

    return NextResponse.json({
      ok: true,
      bill: {
        id: String(bill._id),
        billNumber: bill.billNumber,
        vendorName: bill.vendorName,
        total: bill.total,
        amountPaid: bill.amountPaid,
        status: bill.status,
      },
    });
  } catch (error) {
    console.error("PUT /api/purchases/bills/[id] error:", error);
    return respondError("Failed to update bill.", 500);
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    if (!id || !isValidObjectId(id)) {
      return respondError("Invalid bill ID.", 400);
    }

    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return respondError("Sign in to delete bill.", 401);
    }

    const url = new URL(request.url);
    const requestedOrgId = url.searchParams.get("organizationId") ?? undefined;

    let organizationId = session.user.organizationId;
    if (session.user.id === "admin" && requestedOrgId && isValidObjectId(requestedOrgId)) {
      organizationId = requestedOrgId;
    }

    await connectToDatabase();
    const orgObjId = new Types.ObjectId(organizationId);

    const bill = await PurchaseBill.findOne({
      _id: new Types.ObjectId(id),
      organizationId: orgObjId,
    });

    if (!bill) {
      return respondError("Bill not found.", 404);
    }

    if (bill.amountPaid > 0) {
      return respondError(
        `Cannot delete bill "${bill.billNumber}" because ₹${bill.amountPaid} has already been recorded in payments against it. Delete the payments first.`,
        400,
      );
    }

    await PurchaseBill.deleteOne({ _id: bill._id });

    return NextResponse.json({
      ok: true,
      message: `Bill ${bill.billNumber} deleted successfully.`,
    });
  } catch (error) {
    console.error("DELETE /api/purchases/bills/[id] error:", error);
    return respondError("Failed to delete bill.", 500);
  }
}

import { isValidObjectId, Types } from "mongoose";
import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { PurchaseBill, VendorCredit } from "@/models";
import { formatDateOnly } from "@/lib/bill-utils";

function respondError(message: string, status: number) {
  return NextResponse.json({ error: message }, { status });
}

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    if (!id || !isValidObjectId(id)) {
      return respondError("Invalid bill ID.", 400);
    }

    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return respondError("Sign in to fetch bill vendor credits.", 401);
    }

    const url = new URL(request.url);
    const requestedOrgId = url.searchParams.get("organizationId") ?? undefined;

    let organizationId = session.user.organizationId;
    if (session.user.id === "admin" && requestedOrgId && isValidObjectId(requestedOrgId)) {
      organizationId = requestedOrgId;
    }

    if (!organizationId || !isValidObjectId(organizationId)) {
      return respondError("Valid organization ID is required.", 400);
    }

    await connectToDatabase();
    const orgObjId = new Types.ObjectId(organizationId);
    const billObjId = new Types.ObjectId(id);

    const bill = await PurchaseBill.findOne({ _id: billObjId, organizationId: orgObjId }).lean();
    if (!bill) {
      return respondError("Bill not found.", 404);
    }

    // Find all open/partially-applied vendor credits for this vendor with available balance
    const availableCreditsDb = await VendorCredit.find({
      organizationId: orgObjId,
      vendorId: bill.vendorId,
      status: { $in: ["Open", "Partially Applied"] },
      balanceRemaining: { $gt: 0 },
    })
      .sort({ vendorCreditDate: 1, createdAt: 1 })
      .lean();

    const availableCredits = availableCreditsDb.map((c) => ({
      id: String(c._id),
      creditNoteNumber: c.creditNoteNumber,
      vendorId: String(c.vendorId),
      vendorName: c.vendorName,
      vendorCreditDate: c.vendorCreditDate ? formatDateOnly(new Date(c.vendorCreditDate)) : "",
      subject: c.subject || "",
      total: Number(c.total || 0),
      balanceRemaining: Number(c.balanceRemaining ?? c.total ?? 0),
      appliedAmount: Number(c.appliedAmount || 0),
      status: c.status,
    }));

    const billTotal = Number(bill.total || 0);
    const vendorCreditApplied = Number(bill.vendorCreditApplied || 0);
    const paymentMade = Number(bill.amountPaid || 0);
    const paymentDue = Math.max(0, Math.round((billTotal - vendorCreditApplied - paymentMade) * 100) / 100);

    return NextResponse.json({
      bill: {
        id: String(bill._id),
        billNumber: bill.billNumber,
        vendorId: String(bill.vendorId),
        vendorName: bill.vendorName,
        total: billTotal,
        vendorCreditApplied,
        paymentMade,
        paymentDue,
        status: bill.status,
        creditsApplied: (bill.creditsApplied || []).map((c: any) => ({
          creditId: String(c.creditId),
          creditNoteNumber: c.creditNoteNumber,
          amount: Number(c.amount || 0),
          appliedDate: c.appliedDate ? new Date(c.appliedDate).toISOString() : "",
          notes: c.notes || "",
        })),
      },
      availableCredits,
      totalAvailableCredit: availableCredits.reduce((sum, c) => sum + c.balanceRemaining, 0),
    });
  } catch (error) {
    console.error("GET /api/purchases/bills/[id]/vendor-credits error:", error);
    return respondError("Failed to fetch available vendor credits for this bill.", 500);
  }
}

import { isValidObjectId, Types } from "mongoose";
import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { Customer, DocumentSequence, Item, PurchaseBill, Vendor } from "@/models";
import { calculateBillTotals, calculateDueDate, type BillItemInput } from "@/lib/bill-utils";

function respondError(message: string, status: number) {
  return NextResponse.json({ error: message }, { status });
}

export async function GET(request: Request) {
  try {
    const url = new URL(request.url);
    const requestedOrgId = url.searchParams.get("organizationId") ?? undefined;
    const vendorId = url.searchParams.get("vendorId") ?? undefined;
    const search = url.searchParams.get("search")?.toLowerCase() ?? "";
    const statusFilter = url.searchParams.get("status") ?? "all";
    const startDate = url.searchParams.get("startDate") ?? undefined;
    const endDate = url.searchParams.get("endDate") ?? undefined;
    const unpaidOnly = url.searchParams.get("unpaidOnly") === "true";

    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return respondError("Sign in to view bills.", 401);
    }

    let organizationId = session.user.organizationId;
    if (session.user.id === "admin" && requestedOrgId && isValidObjectId(requestedOrgId)) {
      organizationId = requestedOrgId;
    }

    let isDbConnected = false;
    try {
      await connectToDatabase();
      isDbConnected = true;
    } catch {
      isDbConnected = false;
    }

    let bills: any[] = [];
    let vendors: any[] = [];
    let items: any[] = [];
    let customers: any[] = [];

    if (isDbConnected && organizationId && isValidObjectId(organizationId)) {
      const orgObjId = new Types.ObjectId(organizationId);

      const [vendorsDb, itemsDb, customersDb, billsDb] = await Promise.all([
        Vendor.find({ organizationId: orgObjId }).select("_id name email phone gstin state").sort({ name: 1 }).lean(),
        Item.find({ organizationId: orgObjId, active: true }).select("_id name sku purchasePrice purchaseAccount unit").lean(),
        Customer.find({ organizationId: orgObjId }).select("_id name companyName").sort({ name: 1 }).lean(),
        PurchaseBill.find({ organizationId: orgObjId }).sort({ billDate: -1, createdAt: -1 }).lean(),
      ]);

      vendors = vendorsDb.map((v) => ({
        id: String(v._id),
        name: v.name,
        email: v.email || "",
        phone: v.phone || "",
        gstin: v.gstin || "",
        state: v.state || "",
      }));

      items = itemsDb.map((it) => ({
        id: String(it._id),
        name: it.name,
        sku: it.sku,
        rate: Number(it.purchasePrice || 0),
        account: it.purchaseAccount || "Cost of Goods Sold",
        unit: it.unit || "unit",
      }));

      customers = customersDb.map((c) => ({
        id: String(c._id),
        name: c.name,
        companyName: c.companyName || "",
      }));

      bills = billsDb.map((b) => {
        const total = Number(b.total || 0);
        const amountPaid = Number(b.amountPaid || 0);
        const vendorCreditApplied = Number(b.vendorCreditApplied || 0);
        const balanceDue = Math.max(0, Math.round((total - vendorCreditApplied - amountPaid) * 100) / 100);
        return {
          id: String(b._id),
          billNumber: b.billNumber,
          vendorId: String(b.vendorId),
          vendorName: b.vendorName,
          orderNumber: b.orderNumber || "",
          billDate: b.billDate ? new Date(b.billDate).toISOString() : "",
          dueDate: b.dueDate ? new Date(b.dueDate).toISOString() : "",
          paymentTerms: b.paymentTerms || "Due on Receipt",
          accountsPayable: b.accountsPayable || "Accounts Payable",
          subject: b.subject || "",
          subTotal: Number(b.subTotal || 0),
          discount: Number(b.discount || 0),
          discountType: b.discountType || "percent",
          discountAmount: Number(b.discountAmount || 0),
          taxType: b.taxType || "GST",
          taxRate: Number(b.taxRate || 0),
          taxAmount: Number(b.taxAmount || 0),
          cgst: Number(b.cgst || 0),
          sgst: Number(b.sgst || 0),
          igst: Number(b.igst || 0),
          adjustment: Number(b.adjustment || 0),
          total,
          amountPaid,
          vendorCreditApplied,
          creditsApplied: b.creditsApplied || [],
          balanceDue,
          status: b.status || "Pending",
          items: b.items || [],
          notes: b.notes || "",
          termsAndConditions: b.termsAndConditions || "",
          attachmentsCount: Array.isArray(b.attachments) ? b.attachments.length : 0,
          createdAt: b.createdAt ? new Date(b.createdAt).toISOString() : "",
        };
      });
    }

    // Apply filtering
    let filtered = bills;
    if (vendorId && vendorId !== "all") {
      filtered = filtered.filter((b) => b.vendorId === vendorId);
    }

    if (statusFilter && statusFilter !== "all") {
      filtered = filtered.filter((b) => b.status.toLowerCase() === statusFilter.toLowerCase());
    }

    if (unpaidOnly) {
      filtered = filtered.filter((b) => b.balanceDue > 0);
    }

    if (search) {
      filtered = filtered.filter(
        (b) =>
          b.billNumber.toLowerCase().includes(search) ||
          b.vendorName.toLowerCase().includes(search) ||
          b.orderNumber.toLowerCase().includes(search) ||
          b.subject.toLowerCase().includes(search) ||
          b.notes.toLowerCase().includes(search),
      );
    }

    if (startDate) {
      const sMs = new Date(startDate).getTime();
      filtered = filtered.filter((b) => new Date(b.billDate).getTime() >= sMs);
    }

    if (endDate) {
      const eMs = new Date(endDate).getTime();
      filtered = filtered.filter((b) => new Date(b.billDate).getTime() <= eMs);
    }

    // Summary calculations
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let totalAmount = 0;
    let totalPaid = 0;
    let totalDue = 0;
    let totalOverdue = 0;
    let countDue = 0;
    let countOverdue = 0;

    const counts = {
      total: bills.length,
      draft: 0,
      pending: 0,
      partiallyPaid: 0,
      paid: 0,
      overdue: 0,
      void: 0,
    };

    for (const b of bills) {
      totalAmount += b.total;
      totalPaid += b.amountPaid;
      totalDue += b.balanceDue;

      if (b.balanceDue > 0) {
        countDue++;
      }

      const isOverdue = b.dueDate && new Date(b.dueDate) < today && b.balanceDue > 0;
      if (isOverdue) {
        totalOverdue += b.balanceDue;
        countOverdue++;
        counts.overdue++;
      }

      const st = b.status.toLowerCase();
      if (st === "draft") counts.draft++;
      else if (st === "pending") counts.pending++;
      else if (st === "partially paid") counts.partiallyPaid++;
      else if (st === "paid") counts.paid++;
      else if (st === "void") counts.void++;
    }

    return NextResponse.json({
      bills: filtered,
      vendors,
      items,
      customers,
      metrics: {
        totalBills: bills.length,
        totalBillsValue: Math.round(totalAmount * 100) / 100,
        totalAmount: Math.round(totalAmount * 100) / 100,
        totalPaid: Math.round(totalPaid * 100) / 100,
        totalDue: Math.round(totalDue * 100) / 100,
        totalOverdue: Math.round(totalOverdue * 100) / 100,
        countDue,
        countOverdue,
        counts,
        statusCounts: counts,
      },
    });
  } catch (error) {
    console.error("GET /api/purchases/bills error:", error);
    return respondError("Failed to fetch purchase bills.", 500);
  }
}

export async function POST(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user) {
      return respondError("Sign in to create a purchase bill.", 401);
    }

    let payload: any;
    try {
      payload = await request.json();
    } catch {
      return respondError("Submit valid JSON data.", 400);
    }

    const {
      vendorId,
      billNumber: customBillNumber,
      orderNumber,
      billDate,
      dueDate: customDueDate,
      paymentTerms,
      accountsPayable,
      subject,
      items,
      discount,
      discountType,
      taxType,
      taxRate,
      adjustment,
      notes,
      termsAndConditions,
      attachments,
      status: requestedStatus,
      organizationId: customOrgId,
    } = payload;

    if (!vendorId) {
      return respondError("Please select a vendor.", 400);
    }

    if (!Array.isArray(items) || items.length === 0) {
      return respondError("Please add at least one line item.", 400);
    }

    let organizationId = session.user.organizationId;
    if (session.user.id === "admin" && customOrgId && isValidObjectId(customOrgId)) {
      organizationId = customOrgId;
    }

    if (!organizationId || !isValidObjectId(organizationId)) {
      return respondError("Organization ID is required.", 400);
    }

    await connectToDatabase();
    const orgObjId = new Types.ObjectId(organizationId);

    // Validate vendor exists or get vendor info
    let vendorObjId: Types.ObjectId;
    let vendorName = "Vendor";
    if (isValidObjectId(vendorId)) {
      vendorObjId = new Types.ObjectId(vendorId);
      const vend = await Vendor.findOne({ _id: vendorObjId, organizationId: orgObjId }).select("name");
      if (vend && vend.name) vendorName = String(vend.name);
    } else {
      vendorObjId = new Types.ObjectId();
      if (payload.vendorName) vendorName = String(payload.vendorName);
    }

    // Allocate or validate bill number
    let billNumber = (customBillNumber || "").trim();
    if (!billNumber) {
      const sequence = await DocumentSequence.findOneAndUpdate(
        { organizationId: orgObjId, modelName: "Purchase Bill" },
        { $inc: { nextNumber: 1 } },
        { upsert: true, new: true, setDefaultsOnInsert: true },
      );
      const bSeq = sequence?.nextNumber || 1;
      billNumber = `BILL-${String(bSeq).padStart(4, "0")}`;
    } else {
      // Check for duplicate bill number
      const existing = await PurchaseBill.findOne({
        organizationId: orgObjId,
        billNumber: { $regex: new RegExp(`^${billNumber}$`, "i") },
      });
      if (existing) {
        return respondError(`Bill number "${billNumber}" already exists in your organization.`, 409);
      }
    }

    // Calculate due date
    const finalBillDate = billDate ? new Date(billDate) : new Date();
    let finalDueDate: Date;
    if (customDueDate) {
      finalDueDate = new Date(customDueDate);
    } else {
      const calcStr = calculateDueDate(
        finalBillDate.toISOString().split("T")[0],
        paymentTerms || "Due on Receipt",
      );
      finalDueDate = calcStr ? new Date(calcStr) : finalBillDate;
    }

    // Calculate totals on backend
    const calcOutput = calculateBillTotals({
      items: items.map((it: any) => ({
        itemId: it.itemId,
        name: (it.name || "").trim() || "Item",
        description: (it.description || "").trim(),
        account: it.account || "Cost of Goods Sold",
        quantity: Math.max(0, Number(it.quantity) || 1),
        rate: Math.max(0, Number(it.rate) || 0),
        taxRate: Number(it.taxRate) || 0,
        customerId: it.customerId,
        customerName: it.customerName || "",
        amount: Math.round((Number(it.quantity || 1) * Number(it.rate || 0)) * 100) / 100,
      })),
      discount: Number(discount) || 0,
      discountType: discountType === "amount" ? "amount" : "percent",
      taxType: taxType || "GST",
      taxRate: Number(taxRate) || 0,
      adjustment: Number(adjustment) || 0,
    });

    if (calcOutput.total < 0) {
      return respondError("Bill total cannot be negative.", 400);
    }

    // Validate attachments (max 5 files, <= 10MB each)
    const validatedAttachments: any[] = [];
    if (Array.isArray(attachments)) {
      if (attachments.length > 5) {
        return respondError("A maximum of 5 attachments is allowed per bill.", 400);
      }
      for (const att of attachments) {
        if (att.size && att.size > 10 * 1024 * 1024) {
          return respondError(`File "${att.name}" exceeds the maximum allowed size of 10 MB.`, 400);
        }
        validatedAttachments.push({
          name: att.name || "attachment",
          size: Number(att.size) || 0,
          type: att.type || "",
          dataUrl: att.dataUrl || "",
          uploadedAt: new Date(),
        });
      }
    }

    const billStatus = requestedStatus === "Draft" ? "Draft" : "Pending";

    const newBill = await PurchaseBill.create({
      organizationId: orgObjId,
      billNumber,
      vendorId: vendorObjId,
      vendorName,
      orderNumber: (orderNumber || "").trim(),
      billDate: finalBillDate,
      dueDate: finalDueDate,
      paymentTerms: paymentTerms || "Due on Receipt",
      accountsPayable: accountsPayable || "Accounts Payable",
      subject: (subject || "").trim(),
      items: calcOutput.items,
      subTotal: calcOutput.subTotal,
      discount: Number(discount) || 0,
      discountType: discountType || "percent",
      discountAmount: calcOutput.discountAmount,
      taxType: taxType || "GST",
      taxRate: Number(taxRate) || 0,
      taxAmount: calcOutput.taxAmount,
      cgst: calcOutput.cgst,
      sgst: calcOutput.sgst,
      igst: calcOutput.igst,
      adjustment: calcOutput.adjustment,
      total: calcOutput.total,
      amountPaid: 0,
      status: billStatus,
      notes: (notes || "").trim(),
      termsAndConditions: (termsAndConditions || "").trim(),
      attachments: validatedAttachments,
      currency: "INR",
    });

    return NextResponse.json(
      {
        ok: true,
        bill: {
          id: String(newBill._id),
          billNumber: newBill.billNumber,
          vendorName: newBill.vendorName,
          total: newBill.total,
          balanceDue: newBill.total,
          status: newBill.status,
          billDate: newBill.billDate.toISOString(),
          dueDate: newBill.dueDate ? newBill.dueDate.toISOString() : "",
        },
      },
      { status: 201 },
    );
  } catch (error) {
    console.error("POST /api/purchases/bills error:", error);
    return respondError("Failed to create purchase bill.", 500);
  }
}

