    let payload: any;
    try {
      payload = await request.json();
    } catch {
      return respondError("Valid JSON payload required.", 400);
    }

    await connectToDatabase();
    const orgObjId = new Types.ObjectId(organizationId);

    const report = await CustomReport.findOne({
      _id: new Types.ObjectId(id),
      organizationId: orgObjId,
    });

    if (!report) {
      return respondError("Saved report configuration not found.", 404);
    }

    if (payload.name) report.name = String(payload.name).trim();
    if (payload.description !== undefined) report.description = String(payload.description).trim();
    if (payload.module) report.module = payload.module;
    if (Array.isArray(payload.columns)) report.columns = payload.columns;
    if (payload.filters) report.filters = payload.filters;
    if (payload.sort) report.sort = payload.sort;
    if (payload.groupBy !== undefined) report.groupBy = payload.groupBy;
    if (payload.incrementRun) {
      report.runCount = (report.runCount || 0) + 1;
      report.lastRunAt = new Date();
    }

    await report.save();

    return NextResponse.json({
      ok: true,
      id: String(report._id),
      message: "Report configuration updated.",
    });
  } catch (error: any) {
    return respondError(error.message || "Failed to update report.", 500);
  }
