export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    if (!id || !isValidObjectId(id)) {
      return respondError("Invalid credit note ID.", 400);
    }

    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean().catch(() => null);
      if (defaultOrg) orgId = String(defaultOrg._id);
    }

    if (!orgId) {
      return respondError("Organization not found.", 400);
    }

    const orgObjId = new Types.ObjectId(orgId);
    const cnObjId = new Types.ObjectId(id);

    const creditNote = await SalesDocument.findOne({
      _id: cnObjId,
      organizationId: orgObjId,
      type: "Credit Note",
    });

    if (!creditNote) {
      return respondError("Credit note not found.", 404);
    }

    // If already has applied invoices, restrict altering amounts/customer
    const hasApplications = (creditNote.invoicesApplied || []).length > 0;

    const body = await request.json().catch(() => ({}));

    // Customer cannot change if credits have already been applied
    if (hasApplications && body.customerId && String(body.customerId) !== String(creditNote.customerId)) {
      return respondError("Cannot change customer because credits have already been applied to invoices.", 400);
    }

    if (body.customerId && String(body.customerId) !== String(creditNote.customerId)) {
      const customer: any = await Customer.findOne({
        _id: new Types.ObjectId(body.customerId),
        organizationId: orgObjId,
      }).lean();

      if (!customer) {
        return respondError("Customer not found.", 404);
      }
      creditNote.customerId = customer._id;
      creditNote.customerSnapshot = {
        name: customer.name,
        companyName: customer.companyName,
        gstin: customer.gstin,
        pan: customer.pan,
        email: customer.email,
        phone: customer.phone,
        billingAddress: customer.billingAddress,
        shippingAddress: customer.shippingAddress,
      };
    }

    if (body.referenceNumber !== undefined) {
      creditNote.referenceNumber = String(body.referenceNumber).trim();
    }
    if (body.creditNoteDate) {
      creditNote.issueDate = new Date(body.creditNoteDate);
    }
    if (body.accountsReceivable) {
      creditNote.accountsReceivable = String(body.accountsReceivable).trim();
    }
    if (body.salesperson !== undefined) {
      creditNote.salesperson = String(body.salesperson).trim();
    }
    if (body.subject !== undefined) {
      creditNote.subject = String(body.subject).trim();
    }
    if (body.customerNotes !== undefined) {
      creditNote.customerNotes = String(body.customerNotes).trim();
    }
    if (body.termsAndConditions !== undefined) {
      creditNote.termsAndConditions = String(body.termsAndConditions).trim();
    }

    // If not applied to invoices, items and totals can be updated
    if (!hasApplications && Array.isArray(body.items) && body.items.length > 0) {
      let subTotal = 0;
      const computedItems = body.items.map((it: any) => {
        const qty = Math.max(0.001, parseFloat(it.quantity) || 1);
        const rate = Math.max(0, parseFloat(it.rate) || 0);
        const lineAmt = Math.round(qty * rate * 100) / 100;
        subTotal += lineAmt;

        return {
          itemId: it.itemId && isValidObjectId(it.itemId) ? new Types.ObjectId(it.itemId) : undefined,
          name: String(it.name || "Custom Item").trim(),
          description: String(it.description || "").trim(),
          account: String(it.account || "Sales").trim(),
          quantity: qty,
          rate,
          amount: lineAmt,
        };
      });

      subTotal = Math.round(subTotal * 100) / 100;
      const discountVal = Math.max(0, parseFloat(body.discount) || 0);
      const discountType = body.discountType === "amount" ? "amount" : "percent";
      let discountAmount = 0;
      if (discountType === "percent") {
        discountAmount = Math.round(((subTotal * discountVal) / 100) * 100) / 100;
      } else {
        discountAmount = Math.min(subTotal, discountVal);
      }

      const taxableAmount = Math.max(0, subTotal - discountAmount);
      const tdsTcsType =
        body.tdsTcsType === "TCS" ? "TCS" : body.tdsTcsType === "TDS" ? "TDS" : "None";
      const tdsTcsRate = Math.max(0, parseFloat(body.tdsTcsRate) || 0);
      let tdsTcsAmount = 0;
      if (tdsTcsType !== "None" && tdsTcsRate > 0) {
        tdsTcsAmount = Math.round(((taxableAmount * tdsTcsRate) / 100) * 100) / 100;
      }

      const adjustment = parseFloat(body.adjustment) || 0;
      let total = taxableAmount + adjustment;
      if (tdsTcsType === "TCS") total += tdsTcsAmount;
      else if (tdsTcsType === "TDS") total -= tdsTcsAmount;
      total = Math.max(0, Math.round(total * 100) / 100);

      creditNote.items = computedItems;
      creditNote.subTotal = subTotal;
      creditNote.discount = discountVal;
      creditNote.discountType = discountType;
      creditNote.tdsTcsType = tdsTcsType;
      creditNote.tdsTcsRate = tdsTcsRate;
      creditNote.tdsTcsAmount = tdsTcsAmount;
      creditNote.adjustment = adjustment;

      const oldTotal = Number(creditNote.total || 0);
      creditNote.total = total;
      creditNote.balanceRemaining = Math.max(
        0,
        Math.round((total - Number(creditNote.creditedAmount || 0)) * 100) / 100,
      );

      // Adjust customer unusedCredits difference if status was Open
      if (creditNote.status === "Open") {
        const diff = total - oldTotal;
        if (diff !== 0) {
          await Customer.updateOne(
            { _id: creditNote.customerId },
            { $inc: { unusedCredits: diff } },
          ).catch(() => null);
        }
      }
    }

    // Status transition e.g. Draft -> Open
    if (body.action === "open" && creditNote.status === "Draft") {
      creditNote.status = "Open";
      creditNote.balanceRemaining = Number(creditNote.total || 0);
      await Customer.updateOne(
        { _id: creditNote.customerId },
        { $inc: { unusedCredits: Number(creditNote.total || 0) } },
      ).catch(() => null);
    }

    await creditNote.save();

    return NextResponse.json({
      success: true,
      creditNote: {
        id: String(creditNote._id),
        number: creditNote.number,
        total: creditNote.total,
        status: creditNote.status,
        balanceRemaining: creditNote.balanceRemaining,
      },
    });
  } catch (error) {
    console.error("PUT /api/sales/credit-notes/[id] error:", error);
    return respondError("Failed to update credit note.", 500);
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    if (!id || !isValidObjectId(id)) {
      return respondError("Invalid credit note ID.", 400);
    }

    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean().catch(() => null);
      if (defaultOrg) orgId = String(defaultOrg._id);
    }

    if (!orgId) {
      return respondError("Organization not found.", 400);
    }

    const orgObjId = new Types.ObjectId(orgId);
    const cnObjId = new Types.ObjectId(id);

    const creditNote = await SalesDocument.findOne({
      _id: cnObjId,
      organizationId: orgObjId,
      type: "Credit Note",
    });

    if (!creditNote) {
      return respondError("Credit note not found.", 404);
    }

    if ((creditNote.invoicesApplied || []).length > 0) {
      return respondError(
        "Cannot delete credit note because it has already been applied to invoices. Unapply credits first.",
        400,
      );
    }

    // If status was Open, decrement customer unusedCredits
    if (creditNote.status === "Open" && Number(creditNote.total || 0) > 0) {
      await Customer.updateOne(
        { _id: creditNote.customerId },
        { $inc: { unusedCredits: -Number(creditNote.total || 0) } },
      ).catch(() => null);
    }

    await SalesDocument.deleteOne({ _id: cnObjId, organizationId: orgObjId });

    return NextResponse.json({ success: true, message: "Credit Note deleted successfully." });
  } catch (error) {
    console.error("DELETE /api/sales/credit-notes/[id] error:", error);
    return respondError("Failed to delete credit note.", 500);
  }
}

import { Types } from "mongoose";
import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import { CreditNoteSettings, Organization, SalesDocument } from "@/models";
import {
  findNextAvailableCreditNoteNumber,
  formatCreditNoteNumber,
  getFiscalYear,
  parseNextNumberInput,
} from "@/lib/credit-note-numbering";
import { peekNextCreditNoteNumber } from "@/lib/credit-note-service";

function escapeRegex(text: string): string {
  return text.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, "\\$&");
}

export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean().catch(() => null);
      if (defaultOrg) orgId = String(defaultOrg._id);
    }

    if (!orgId) {
      return NextResponse.json({ error: "Organization not found" }, { status: 400 });
    }

    const orgObjId = new Types.ObjectId(orgId);
    const peek = await peekNextCreditNoteNumber(orgObjId);

    const settingsPayload = {
      autoGenerateNumbering: peek.autoGenerateNumbering,
      creditNotePrefix: peek.prefix,
      prefix: peek.prefix,
      nextNumber: peek.nextNumber,
      numberZeroPadding: peek.padding,
      restartNumberingEachFiscalYear: peek.restartNumberingEachFiscalYear,
      lastFiscalYear: peek.lastFiscalYear,
    };

    return NextResponse.json({
      settings: settingsPayload,
      preferences: settingsPayload,
      formattedNextNumber: peek.creditNoteNumber,
    });
  } catch (error: unknown) {
    console.error("GET /api/sales/credit-notes/preferences error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Internal Server Error" },
      { status: 500 },
    );
  }
}

export async function PUT(request: Request) {
  try {
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean().catch(() => null);
      if (defaultOrg) orgId = String(defaultOrg._id);
    }

    if (!orgId) {
      return NextResponse.json({ error: "Organization not found" }, { status: 400 });
    }

    const orgObjId = new Types.ObjectId(orgId);
    const body = await request.json().catch(() => ({}));

    const autoGenerateNumbering = body.autoGenerateNumbering !== false;
    const isAuto = autoGenerateNumbering;

    const rawPrefix = String(body.creditNotePrefix ?? body.prefix ?? "CN-").trim();
    const prefix = isAuto ? rawPrefix || "CN-" : rawPrefix;

    const parsedNum = parseNextNumberInput(body.nextNumber ?? "00002");
    let nextNumber = Math.max(1, body.nextNumber ? parsedNum.nextNumber : 2);
    const numberZeroPadding = Math.max(
      1,
      body.numberZeroPadding ? Number(body.numberZeroPadding) : parsedNum.padding,
    );
    const restartNumberingEachFiscalYear = isAuto
      ? Boolean(body.restartNumberingEachFiscalYear)
      : false;
    const currentFY = getFiscalYear();

    // If auto-generate is enabled, ensure nextNumber does not collide with existing credit notes
    if (isAuto) {
      const existingNotes = await SalesDocument.find({
        organizationId: orgObjId,
        type: "Credit Note",
        number: { $regex: `^${escapeRegex(prefix)}` },
      })
        .select("number")
        .lean();

      const existingSet = new Set(existingNotes.map((n) => n.number));
      const nextAvailable = findNextAvailableCreditNoteNumber(
        prefix,
        nextNumber,
        numberZeroPadding,
        existingSet,
      );
      nextNumber = nextAvailable.allocatedNumber;
    }

    const updated = await CreditNoteSettings.findOneAndUpdate(
      { organizationId: orgObjId },
      {
        $set: {
          autoGenerateNumbering,
          creditNotePrefix: prefix,
          nextNumber,
          numberZeroPadding,
          restartNumberingEachFiscalYear,
          lastFiscalYear: currentFY,
        },
      },
      { new: true, upsert: true },
    ).lean();

    const formattedNextNumber = formatCreditNoteNumber(prefix, nextNumber, numberZeroPadding);

    const settingsPayload = {
      autoGenerateNumbering: updated.autoGenerateNumbering !== false,
      creditNotePrefix: updated.creditNotePrefix || "CN-",
      prefix: updated.creditNotePrefix || "CN-",
      nextNumber: updated.nextNumber || nextNumber,
      numberZeroPadding: updated.numberZeroPadding || numberZeroPadding,
      restartNumberingEachFiscalYear: Boolean(updated.restartNumberingEachFiscalYear),
      lastFiscalYear: updated.lastFiscalYear || currentFY,
    };

    return NextResponse.json({
      success: true,
      settings: settingsPayload,
      preferences: settingsPayload,
      formattedNextNumber,
    });
  } catch (error: unknown) {
    console.error("PUT /api/sales/credit-notes/preferences error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Internal Server Error" },
      { status: 500 },
    );
  }
}

import { isValidObjectId, Types } from "mongoose";
import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";
import { authOptions } from "@/lib/auth";
import { connectToDatabase } from "@/lib/db";
import {
  CreditNoteSettings,
  Customer,
  Organization,
  SalesDocument,
} from "@/models";
import {
  formatCreditNoteNumber,
  extractNumberPart,
} from "@/lib/credit-note-numbering";
import { allocateNextCreditNoteNumber } from "@/lib/credit-note-service";

export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean().catch(() => null);
      if (defaultOrg) orgId = String(defaultOrg._id);
    }

    if (!orgId) {
      return NextResponse.json({ error: "Organization not found" }, { status: 400 });
    }

    const orgObjId = new Types.ObjectId(orgId);
    const url = new URL(request.url);
    const search = url.searchParams.get("search")?.trim().toLowerCase();
    const statusParam = url.searchParams.get("status")?.trim();
    const customerId = url.searchParams.get("customerId")?.trim();

    const query: Record<string, unknown> = {
      organizationId: orgObjId,
      type: "Credit Note",
    };

    if (customerId && isValidObjectId(customerId)) {
      query.customerId = new Types.ObjectId(customerId);
    }

    if (statusParam && statusParam.toUpperCase() !== "ALL") {
      const statusMap: Record<string, string> = {
        draft: "Draft",
        open: "Open",
        partially_applied: "Partially Applied",
        "partially applied": "Partially Applied",
        closed: "Closed",
        void: "Void",
      };
      const mapped = statusMap[statusParam.toLowerCase()] || statusParam;
      query.status = mapped;
    }

    const [notesDocs, customersDocs] = await Promise.all([
      SalesDocument.find(query).sort({ issueDate: -1, createdAt: -1 }).lean(),
      Customer.find({ organizationId: orgObjId })
        .select("_id name companyName")
        .sort({ name: 1 })
        .lean(),
    ]);

    let notes = notesDocs.map((doc: any) => {
      const total = Number(doc.total || 0);
      const credited = Number(doc.creditedAmount || 0);
      const balance =
        doc.balanceRemaining !== undefined
          ? Number(doc.balanceRemaining)
          : Math.max(0, Math.round((total - credited) * 100) / 100);

      return {
        id: String(doc._id),
        creditNoteNumber: doc.number,
        customerId: String(doc.customerId),
        customerName:
          doc.customerSnapshot?.companyName ||
          doc.customerSnapshot?.name ||
          "Unknown Customer",
        referenceNumber: doc.referenceNumber || "",
        creditNoteDate: doc.issueDate ? new Date(doc.issueDate).toISOString() : "",
        status: doc.status || "Draft",
        total,
        appliedAmount: credited,
        balanceRemaining: balance,
        subject: doc.subject || "",
        salesperson: doc.salesperson || "",
        accountsReceivable: doc.accountsReceivable || "Accounts Receivable",
        createdAt: doc.createdAt ? new Date(doc.createdAt).toISOString() : "",
      };
    });

    if (search) {
      notes = notes.filter((n) => {
        return (
          n.creditNoteNumber.toLowerCase().includes(search) ||
          n.customerName.toLowerCase().includes(search) ||
          n.referenceNumber.toLowerCase().includes(search) ||
          n.subject.toLowerCase().includes(search)
        );
      });
    }

    // Calculate metrics across all credit notes in this organization
    const allNotes = await SalesDocument.find({
      organizationId: orgObjId,
      type: "Credit Note",
    })
      .select("status total creditedAmount balanceRemaining")
      .lean();

    let totalCreditAmount = 0;
    let totalApplied = 0;
    let totalAvailable = 0;
    const statusCounts = {
      total: allNotes.length,
      draft: 0,
      open: 0,
      partiallyApplied: 0,
      closed: 0,
      void: 0,
    };

    for (const n of allNotes) {
      const tot = Number(n.total || 0);
      const applied = Number(n.creditedAmount || 0);
      const bal =
        n.balanceRemaining !== undefined
          ? Number(n.balanceRemaining)
          : Math.max(0, Math.round((tot - applied) * 100) / 100);

      if (n.status !== "Void") {
        totalCreditAmount += tot;
        totalApplied += applied;
        if (n.status === "Open" || n.status === "Partially Applied") {
          totalAvailable += bal;
        }
      }

      if (n.status === "Draft") statusCounts.draft++;
      else if (n.status === "Open") statusCounts.open++;
      else if (n.status === "Partially Applied") statusCounts.partiallyApplied++;
      else if (n.status === "Closed") statusCounts.closed++;
      else if (n.status === "Void") statusCounts.void++;
    }

    return NextResponse.json({
      creditNotes: notes,
      customers: customersDocs.map((c: any) => ({
        id: String(c._id),
        name: c.companyName ? `${c.companyName} (${c.name})` : c.name,
      })),
      metrics: {
        totalCreditNotes: allNotes.length,
        totalCreditAmount: Math.round(totalCreditAmount * 100) / 100,
        totalApplied: Math.round(totalApplied * 100) / 100,
        totalAvailable: Math.round(totalAvailable * 100) / 100,
        statusCounts,
      },
    });
  } catch (error: unknown) {
    console.error("GET /api/sales/credit-notes error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Internal Server Error" },
      { status: 500 },
    );
  }
}

export async function POST(request: Request) {
  try {
    const session = await getServerSession(authOptions).catch(() => null);
    await connectToDatabase().catch(() => null);

    let orgId = session?.user?.organizationId;
    if (!orgId) {
      const defaultOrg = await Organization.findOne().select("_id").lean().catch(() => null);
      if (defaultOrg) orgId = String(defaultOrg._id);
    }

    if (!orgId) {
      return NextResponse.json({ error: "Organization not found" }, { status: 400 });
    }

    const orgObjId = new Types.ObjectId(orgId);
    const body = await request.json().catch(() => ({}));

    if (!body.customerId || !isValidObjectId(body.customerId)) {
      return NextResponse.json({ error: "Please select a valid customer." }, { status: 400 });
    }

    const customer = await Customer.findOne({
      _id: new Types.ObjectId(body.customerId),
      organizationId: orgObjId,
    }).lean();

    if (!customer) {
      return NextResponse.json({ error: "Customer not found in this organization." }, { status: 404 });
    }

    // Numbering resolution
    const settings = await CreditNoteSettings.findOne({ organizationId: orgObjId }).lean();
    const isAuto =
      body.autoGenerateNumbering !== undefined
        ? Boolean(body.autoGenerateNumbering)
        : settings ? settings.autoGenerateNumbering !== false : true;

    let creditNoteNumber = String(body.creditNoteNumber || body.number || "").trim();

    if (!isAuto) {
      // Manual entry mode
      if (!creditNoteNumber) {
        return NextResponse.json(
          { error: "Credit Note Number is required when manual numbering is enabled." },
          { status: 400 },
        );
      }

      const existing = await SalesDocument.findOne({
        organizationId: orgObjId,
        type: "Credit Note",
        number: creditNoteNumber,
      }).lean();

      if (existing) {
        return NextResponse.json(
          { error: `Credit Note Number '${creditNoteNumber}' already exists.` },
          { status: 409 },
        );
      }
    } else {
      // Auto-generate mode
      const prefix = settings?.creditNotePrefix || "CN-";

      // Check whether creditNoteNumber is empty, already taken in DB, or matches the auto-prefix pattern
      let isAlreadyTaken = false;
      if (creditNoteNumber) {
        const existingDoc = await SalesDocument.findOne({
          organizationId: orgObjId,
          type: "Credit Note",
          number: creditNoteNumber,
        })
          .select("_id")
          .lean();
        isAlreadyTaken = Boolean(existingDoc);
      }

      const isPrefixMatch = creditNoteNumber ? creditNoteNumber.startsWith(prefix) : false;

      // In auto-generate mode:
      // If no number was provided, OR the number is already taken (e.g. CN-00002), OR it matches the sequential prefix:
      // Automatically allocate the next available unique sequential number!
      if (!creditNoteNumber || isAlreadyTaken || isPrefixMatch) {
        try {
          const allocated = await allocateNextCreditNoteNumber(orgObjId);
          creditNoteNumber = allocated.creditNoteNumber;
        } catch {
          creditNoteNumber = `CN-${Math.floor(10000 + Math.random() * 90000)}`;
        }
      } else {
        // User provided custom manual number with different prefix while in auto mode
        const existing = await SalesDocument.findOne({
          organizationId: orgObjId,
          type: "Credit Note",
          number: creditNoteNumber,
        }).lean();

        if (existing) {
          return NextResponse.json(
            { error: `Credit Note Number '${creditNoteNumber}' already exists.` },
            { status: 409 },
          );
        }

        const numPart = extractNumberPart(creditNoteNumber, prefix);
        if (numPart) {
          await CreditNoteSettings.updateOne(
            { organizationId: orgObjId, nextNumber: { $lte: numPart } },
            { $set: { nextNumber: numPart + 1 } },
          ).catch(() => null);
        }
      }
    }

    // Items line calculation
    const rawItems: any[] = Array.isArray(body.items) ? body.items : [];
    if (rawItems.length === 0) {
      return NextResponse.json(
        { error: "At least one item is required in the Credit Note." },
        { status: 400 },
      );
    }

    let subTotal = 0;
    const computedItems = rawItems.map((it: any) => {
      const qty = Math.max(0.001, parseFloat(it.quantity) || 1);
      const rate = Math.max(0, parseFloat(it.rate) || 0);
      const lineAmt = Math.round(qty * rate * 100) / 100;
      subTotal += lineAmt;

      return {
        itemId: it.itemId && isValidObjectId(it.itemId) ? new Types.ObjectId(it.itemId) : undefined,
        name: String(it.name || "Custom Item").trim(),
        description: String(it.description || "").trim(),
        account: String(it.account || "Sales").trim(),
        quantity: qty,
        rate,
        amount: lineAmt,
      };
    });

    subTotal = Math.round(subTotal * 100) / 100;

    // Discount
    const discountVal = Math.max(0, parseFloat(body.discount) || 0);
    const discountType = body.discountType === "amount" ? "amount" : "percent";
    let discountAmount = 0;
    if (discountType === "percent") {
      discountAmount = Math.round(((subTotal * discountVal) / 100) * 100) / 100;
    } else {
      discountAmount = Math.min(subTotal, discountVal);
    }

    const taxableAmount = Math.max(0, subTotal - discountAmount);

    // Tax / TDS / TCS
    const tdsTcsType =
      body.tdsTcsType === "TCS" ? "TCS" : body.tdsTcsType === "TDS" ? "TDS" : "None";
    const tdsTcsRate = Math.max(0, parseFloat(body.tdsTcsRate) || 0);
    let tdsTcsAmount = 0;
    if (tdsTcsType !== "None" && tdsTcsRate > 0) {
      tdsTcsAmount = Math.round(((taxableAmount * tdsTcsRate) / 100) * 100) / 100;
    }

    // Adjustment
    const adjustment = parseFloat(body.adjustment) || 0;

    // Grand Total
    let total = taxableAmount + adjustment;
    if (tdsTcsType === "TCS") {
      total += tdsTcsAmount;
    } else if (tdsTcsType === "TDS") {
      total -= tdsTcsAmount;
    }
    total = Math.max(0, Math.round(total * 100) / 100);

    const targetStatus =
      body.status === "Draft" || body.action === "draft" ? "Draft" : "Open";
    const balanceRemaining = targetStatus === "Draft" ? 0 : total;

    const creditNote = new SalesDocument({
      organizationId: orgObjId,
      type: "Credit Note",
      number: creditNoteNumber,
      customerId: customer._id,
      customerSnapshot: {
        name: customer.name,
        companyName: customer.companyName,
        gstin: customer.gstin,
        pan: customer.pan,
        email: customer.email,
        phone: customer.phone,
        billingAddress: customer.billingAddress,
        shippingAddress: customer.shippingAddress,
      },
      referenceNumber: String(body.referenceNumber || "").trim(),
      issueDate: body.creditNoteDate ? new Date(body.creditNoteDate) : new Date(),
      status: targetStatus,
      accountsReceivable: String(body.accountsReceivable || "Accounts Receivable").trim(),
      salesperson: String(body.salesperson || "").trim(),
      subject: String(body.subject || "").trim(),
      items: computedItems,
      subTotal,
      discount: discountVal,
      discountType,
      tdsTcsType,
      tdsTcsRate,
      tdsTcsAmount,
      adjustment,
      total,
      creditedAmount: 0,
      balanceRemaining,
      customerNotes: String(body.customerNotes || "").trim(),
      termsAndConditions: String(body.termsAndConditions || "").trim(),
      invoicesApplied: [],
      creditsApplied: [],
    });

    // Save with automatic collision retry on duplicate key (E11000) for concurrency safety
    const maxRetries = 5;
    let saved = false;
    let lastSaveError: any = null;

    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        creditNote.number = creditNoteNumber;
        await creditNote.save();
        saved = true;
        break;
      } catch (saveErr: any) {
        lastSaveError = saveErr;
        const isDuplicateKey =
          saveErr?.code === 11000 ||
          saveErr?.message?.includes("E11000") ||
          saveErr?.message?.includes("duplicate key");

        if (isDuplicateKey && isAuto) {
          try {
            const reallocated = await allocateNextCreditNoteNumber(orgObjId);
            creditNoteNumber = reallocated.creditNoteNumber;
            continue;
          } catch {
            // fall through to throw
          }
        }
        throw saveErr;
      }
    }

    if (!saved) {
      throw lastSaveError || new Error("Failed to allocate a unique credit note number.");
    }

    // If opened immediately, update customer unused credits
    if (targetStatus === "Open" && total > 0) {
      await Customer.updateOne(
        { _id: customer._id },
        { $inc: { unusedCredits: total } },
      ).catch(() => null);
    }

    return NextResponse.json(
      {
        success: true,
        creditNote: {
          id: String(creditNote._id),
          number: creditNote.number,
          total: creditNote.total,
          status: creditNote.status,
          balanceRemaining: creditNote.balanceRemaining,
        },
      },
      { status: 201 },
    );
  } catch (error: unknown) {
