"use client";

import { useCallback, useEffect, useState } from "react";
import {
  ClipboardList,
  Clock,
  CheckCircle2,
  AlertCircle,
  RefreshCw,
  ShieldCheck,
  Building2,
  Calendar,
  MapPin,
  Package,
  X,
  Check,
} from "lucide-react";

type AdminStatus = "Pending" | "Approved";

interface AdminBuyingRequestItem {
  id: string;
  requestId: string;
  organizationId: string;
  organizationName: string;
  commodity: string;
  requiredQuantity: number;
  unit: string;
  targetPrice: number | null;
  deliveryLocation: string;
  requiredDeliveryDate: string;
  buyerName: string;
  buyerCompany: string;
  status: string;
  adminStatus: AdminStatus;
  offersCount: number;
  createdAt: string;
}

type TabFilter = "Pending" | "Approved" | "all";

export function AdminBuyingRequests() {
  const [requests, setRequests] = useState<AdminBuyingRequestItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabFilter>("Pending");
  const [busyId, setBusyId] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ type: "success" | "error"; message: string } | null>(null);
  const [total, setTotal] = useState(0);

  const loadRequests = useCallback(async (tab: TabFilter) => {
    setLoading(true);
    setFeedback(null);
    try {
      const params = new URLSearchParams({ adminStatus: tab, limit: "50" });
      const res = await fetch(`/api/admin/buying-requests?${params.toString()}`, { cache: "no-store" });
      const data = await res.json() as { requests?: AdminBuyingRequestItem[]; total?: number; error?: string };
      if (!res.ok) throw new Error(data.error ?? "Failed to load buying requests");
      setRequests(data.requests ?? []);
      setTotal(data.total ?? 0);
    } catch (err) {
      setFeedback({
        type: "error",
        message: err instanceof Error ? err.message : "Failed to load requests",
      });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadRequests(activeTab);
  }, [activeTab, loadRequests]);

  const handleApprove = async (req: AdminBuyingRequestItem) => {
    setBusyId(req.id);
    setFeedback(null);
    try {
      const res = await fetch(`/api/admin/buying-requests/${req.id}/approve`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      });
      const data = await res.json() as { ok?: boolean; message?: string; error?: string };
      if (!res.ok) throw new Error(data.error ?? "Failed to approve request");
      setFeedback({ type: "success", message: data.message ?? "Request approved successfully." });
      // Refresh the list
      await loadRequests(activeTab);
    } catch (err) {
      setFeedback({
        type: "error",
        message: err instanceof Error ? err.message : "Failed to approve request",
      });
    } finally {
      setBusyId(null);
    }
  };

  const getAdminStatusBadge = (adminStatus: AdminStatus) => {
    if (adminStatus === "Approved") {
      return (
        <span className="inline-flex items-center gap-1 rounded-full bg-emerald-100 px-2.5 py-0.5 text-xs font-semibold text-emerald-800 border border-emerald-200">
          <ShieldCheck className="h-3 w-3" /> Approved
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-semibold text-amber-800 border border-amber-200">
        <Clock className="h-3 w-3" /> Pending Approval
      </span>
    );
  };

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold tracking-tight text-slate-900">Buying Requests Approval</h1>
            <span className="rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-semibold text-amber-800">
              Admin Panel
            </span>
          </div>
          <p className="mt-1 text-sm text-slate-600">
            Review and approve buying requests submitted by users across all organizations.
          </p>
        </div>
        <button
          type="button"
          onClick={() => void loadRequests(activeTab)}
          className="inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-50 shadow-sm"
        >
          <RefreshCw className={`h-3.5 w-3.5 ${loading ? "animate-spin text-emerald-600" : ""}`} />
          Refresh
        </button>
      </div>

      {/* Feedback Toast */}
      {feedback && (
        <div
          className={`flex items-center justify-between rounded-xl p-4 text-sm shadow-sm ${
            feedback.type === "success"
              ? "bg-emerald-50 text-emerald-900 border border-emerald-200"
              : "bg-red-50 text-red-900 border border-red-200"
          }`}
        >
          <div className="flex items-center gap-2">
            {feedback.type === "success" ? (
              <CheckCircle2 className="h-5 w-5 text-emerald-600 shrink-0" />
            ) : (
              <AlertCircle className="h-5 w-5 text-red-600 shrink-0" />
            )}
            <span>{feedback.message}</span>
          </div>
          <button type="button" onClick={() => setFeedback(null)} className="rounded p-1 hover:bg-black/5">
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Tabs */}
      <div className="flex flex-wrap items-center gap-2 border-b border-slate-200 pb-3">
        {(["Pending", "Approved", "all"] as TabFilter[]).map((tab) => (
          <button
            key={tab}
            type="button"
            onClick={() => setActiveTab(tab)}
            className={`rounded-xl px-4 py-2 text-sm font-semibold transition ${
              activeTab === tab
                ? tab === "Pending"
                  ? "bg-amber-600 text-white shadow-sm"
                  : tab === "Approved"
                  ? "bg-emerald-600 text-white shadow-sm"
                  : "bg-slate-900 text-white shadow-sm"
                : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
            }`}
          >
            {tab === "Pending" ? "⏳ Pending Approval" : tab === "Approved" ? "✅ Approved" : "All Requests"}
          </button>
        ))}
        <span className="ml-auto text-xs text-slate-500 font-medium">
          {loading ? "Loading..." : `${total} request${total !== 1 ? "s" : ""}`}
        </span>
      </div>

      {/* Request List */}
      {loading ? (
        <div className="space-y-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="animate-pulse rounded-2xl border border-slate-200 bg-white p-5 space-y-3">
              <div className="h-5 w-40 rounded bg-slate-200" />
              <div className="h-4 w-64 rounded bg-slate-200" />
              <div className="h-10 w-full rounded-xl bg-slate-100" />
            </div>
          ))}
        </div>
      ) : requests.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-12 text-center">
          <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-slate-100 text-slate-400">
            <ClipboardList className="h-7 w-7" />
          </div>
          <h3 className="mt-4 text-base font-semibold text-slate-900">
            {activeTab === "Pending"
              ? "No pending requests"
              : activeTab === "Approved"
              ? "No approved requests"
              : "No buying requests found"}
          </h3>
          <p className="mt-1 text-sm text-slate-500">
            {activeTab === "Pending"
              ? "All buying requests have been reviewed. No pending approvals at this time."
              : "No requests match this filter."}
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {requests.map((req) => (
            <div
              key={req.id}
              className={`rounded-2xl border p-5 shadow-sm transition ${
                req.adminStatus === "Approved"
                  ? "border-emerald-200 bg-emerald-50/30"
                  : "border-slate-200 bg-white hover:border-slate-300"
              }`}
            >
              <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                {/* Left Column */}
                <div className="space-y-2 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-mono text-xs font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded-md">
                      {req.requestId}
                    </span>
                    {getAdminStatusBadge(req.adminStatus)}
                    <span className="inline-flex items-center gap-1 rounded-full bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-600">
                      {req.status}
                    </span>
                    <span className="text-xs text-slate-400">
                      Posted {new Date(req.createdAt).toLocaleDateString()}
                    </span>
                  </div>

                  <div>
                    <h3 className="text-lg font-bold text-slate-900">{req.commodity}</h3>
                    <p className="text-xs text-slate-500">
                      by <span className="font-semibold text-slate-700">{req.buyerCompany}</span> ({req.buyerName})
                    </p>
                  </div>

                  <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 rounded-xl bg-slate-50 p-3 text-xs">
                    <div>
                      <span className="text-slate-400 flex items-center gap-1 mb-0.5">
                        <Package className="h-3 w-3" /> Quantity
                      </span>
                      <span className="font-bold text-slate-900">
                        {req.requiredQuantity} {req.unit}
                      </span>
                    </div>
                    <div>
                      <span className="text-slate-400 block mb-0.5">Target Price</span>
                      <span className="font-bold text-slate-900">
                        {req.targetPrice
                          ? `₹${req.targetPrice.toLocaleString("en-IN")}/${req.unit}`
                          : "Open to Bids"}
                      </span>
                    </div>
                    <div>
                      <span className="text-slate-400 flex items-center gap-1 mb-0.5">
                        <Calendar className="h-3 w-3" /> Delivery By
                      </span>
                      <span className="font-semibold text-slate-900">
                        {new Date(req.requiredDeliveryDate).toLocaleDateString()}
                      </span>
                    </div>
                    <div>
                      <span className="text-slate-400 flex items-center gap-1 mb-0.5">
                        <Building2 className="h-3 w-3" /> Organization
                      </span>
                      <span className="font-semibold text-slate-900 truncate block" title={req.organizationName}>
                        {req.organizationName}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-1 text-xs text-slate-600">
                    <MapPin className="h-3.5 w-3.5 text-slate-400 shrink-0" />
                    <span>{req.deliveryLocation}</span>
                  </div>
                </div>

                {/* Right Column: Actions */}
                <div className="flex flex-wrap items-center gap-2 lg:flex-col lg:items-end lg:justify-center shrink-0">
                  {req.adminStatus === "Pending" ? (
                    <button
                      type="button"
                      disabled={busyId === req.id}
                      onClick={() => void handleApprove(req)}
                      className="inline-flex items-center gap-1.5 rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-blue-700 transition disabled:opacity-50"
                    >
                      <Check className="h-4 w-4" />
                      {busyId === req.id ? "Approving..." : "Approve Request"}
                    </button>
                  ) : (
                    <div className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-50 border border-emerald-200 px-4 py-2.5 text-sm font-semibold text-emerald-700">
                      <ShieldCheck className="h-4 w-4" />
                      Approved
                    </div>
                  )}
                  {req.offersCount > 0 && (
                    <span className="rounded-full bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-800 border border-amber-200">
                      {req.offersCount} {req.offersCount === 1 ? "Offer" : "Offers"}
                    </span>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { signIn } from "next-auth/react";
import { useRouter } from "next/navigation";
import { useState, useRef, type FormEvent, type ChangeEvent, type DragEvent } from "react";
import {
  Building2,
  CheckCircle2,
  ChevronDown,
  ChevronUp,
  FileText,
  Image as ImageIcon,
  Landmark,
  ShieldCheck,
  Upload,
  X,
} from "lucide-react";
import {
  INDIAN_STATES,
  PAN_REGEX,
  AADHAAR_REGEX,
  GSTIN_REGEX,
  IFSC_REGEX,
  formatAadhaarDisplay,
  sanitizeAadhaar,
} from "@/lib/indian-states";

type AuthFormProps =
  | { mode: "signin" }
  | { mode: "admin"; adminEmail: string }
  | { mode: "signup" };

const inputClassName =
  "mt-1.5 w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10";

export function AuthForm(props: AuthFormProps) {
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOptionalFields, setShowOptionalFields] = useState(false);

  // Optional form state
  const [pan, setPan] = useState("");
  const [aadhaar, setAadhaar] = useState("");
  const [gstin, setGstin] = useState("");
  const [address, setAddress] = useState("");
  const [selectedState, setSelectedState] = useState("");
  const [accountHolderName, setAccountHolderName] = useState("");
  const [accountNumber, setAccountNumber] = useState("");
  const [ifsc, setIfsc] = useState("");
  const [bankName, setBankName] = useState("");
  const [branch, setBranch] = useState("");

  // Logo state
  const [logoData, setLogoData] = useState<string>("");
  const [logoFileName, setLogoFileName] = useState<string>("");
  const [isDragging, setIsDragging] = useState(false);

  // Inline format warnings
  const [panError, setPanError] = useState("");
  const [aadhaarError, setAadhaarError] = useState("");
  const [gstinError, setGstinError] = useState("");
  const [ifscError, setIfscError] = useState("");

  const isSignup = props.mode === "signup";
  const isAdmin = props.mode === "admin";

  // Handle PAN input
  const handlePanChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.toUpperCase().slice(0, 10);
    setPan(val);
    if (val && !PAN_REGEX.test(val)) {
      setPanError("Format: 5 letters, 4 digits, 1 letter (e.g. ABCDE1234F)");
    } else {
      setPanError("");
    }
  };

  // Handle Aadhaar input
  const handleAadhaarChange = (e: ChangeEvent<HTMLInputElement>) => {
    const raw = sanitizeAadhaar(e.target.value).slice(0, 12);
    setAadhaar(raw);
    if (raw && raw.length !== 12) {
      setAadhaarError("Aadhaar must be a 12-digit number");
    } else {
      setAadhaarError("");
    }
  };

  // Handle GSTIN input
  const handleGstinChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.toUpperCase().slice(0, 15);
    setGstin(val);
    if (val && !GSTIN_REGEX.test(val)) {
      setGstinError("Format: 15 characters (e.g. 27ABCDE1234F1Z5)");
    } else {
      setGstinError("");
    }
  };

  // Handle IFSC input
  const handleIfscChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.toUpperCase().slice(0, 11);
    setIfsc(val);
    if (val && !IFSC_REGEX.test(val)) {
      setIfscError("Format: 4 letters, 0, 6 alphanumeric (e.g. HDFC0001234)");
    } else {
      setIfscError("");
    }
  };

  // Handle Logo file upload
  const processLogoFile = (file: File) => {
    if (!file.type.startsWith("image/")) {
      setError("Please upload an image file (PNG, JPG, WEBP, or SVG).");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setError("Company logo size must be under 5MB.");
      return;
    }
    setError("");
    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      setLogoData(result);
      setLogoFileName(file.name);
    };
    reader.readAsDataURL(file);
  };

  const handleFileInput = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processLogoFile(file);
    }
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) {
      processLogoFile(file);
    }
  };

  const removeLogo = () => {
    setLogoData("");
    setLogoFileName("");
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setSuccess("");

    // Validate optional fields only if provided
    if (pan && !PAN_REGEX.test(pan)) {
      setError("Please provide a valid PAN format (e.g. ABCDE1234F) or leave it empty.");
      return;
    }
    if (aadhaar && aadhaar.length !== 12) {
      setError("Please provide a valid 12-digit Aadhaar number or leave it empty.");
      return;
    }
    if (gstin && !GSTIN_REGEX.test(gstin)) {
      setError("Please provide a valid 15-character GSTIN (e.g. 27ABCDE1234F1Z5) or leave it empty.");
      return;
    }
    if (ifsc && !IFSC_REGEX.test(ifsc)) {
      setError("Please provide a valid IFSC code (e.g. HDFC0001234) or leave it empty.");
      return;
    }

    setIsSubmitting(true);

    const formData = new FormData(event.currentTarget);
    const email = isAdmin ? props.adminEmail : String(formData.get("email") ?? "");
    const password = String(formData.get("password") ?? "");

    try {
      if (isSignup) {
        const payload: Record<string, unknown> = {
          name: formData.get("name"),
          organizationName: formData.get("organizationName"),
          email,
          password,
        };

        if (pan) payload.pan = pan;
        if (aadhaar) payload.aadhaar = aadhaar;
        if (gstin) payload.gstin = gstin;
        if (logoData) payload.logo = logoData;
        if (address) payload.address = address;
        if (selectedState) payload.state = selectedState;

        if (accountHolderName || accountNumber || ifsc || bankName || branch) {
          payload.bankDetails = {
            accountHolderName: accountHolderName || undefined,
            accountNumber: accountNumber || undefined,
            ifsc: ifsc || undefined,
            bankName: bankName || undefined,
            branch: branch || undefined,
          };
        }

        const response = await fetch("/api/signup", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
        const result = (await response.json()) as { error?: string; pendingApproval?: boolean };
        if (!response.ok) {
          setError(result.error ?? "Unable to create your account.");
          return;
        }
        setSuccess(
          result.pendingApproval
            ? "Your organization request was submitted with all provided details. An administrator must approve it before you can sign in."
            : "Your account is ready. Sign in to continue.",
        );
        return;
      }

      const result = await signIn("credentials", {
        email,
        password,
        redirect: false,
      });
      if (!result || result.error) {
        setError("The email or password is incorrect.");
        return;
      }

      router.replace("/");
      router.refresh();
    } catch {
      setError(isSignup ? "Unable to create your account right now." : "Unable to sign in right now.");
    } finally {
      setIsSubmitting(false);
    }
  }

  const title = isSignup ? "Create your account" : isAdmin ? "Admin sign in" : "Welcome back";
  const description = isSignup
    ? "Set up your organization and start managing your finances."
    : isAdmin
      ? "Sign in to the BharatGodam administration dashboard."
      : "Sign in to continue to your BharatGodam dashboard.";

  return (
    <main className="flex min-h-screen items-center justify-center bg-slate-100 px-4 py-10">
      <section
        className={`w-full ${
          isSignup ? "max-w-2xl" : "max-w-md"
        } rounded-3xl border border-slate-200 bg-white p-7 shadow-xl shadow-slate-900/5 sm:p-9 transition-all duration-300`}
      >
        <Link
          href="/"
          className="inline-block transition-opacity hover:opacity-90 focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 rounded-lg"
          title="BharatGodam"
          aria-label="BharatGodam Home"
        >
          <img
            src="/bharatgodam-logo.jpg"
            alt="BharatGodam Logo"
            className="h-12 sm:h-14 w-auto max-w-[200px] object-contain"
            style={{ objectFit: "contain", aspectRatio: "1024 / 458" }}
          />
        </Link>
        <h1 className="mt-5 text-2xl font-semibold tracking-tight text-slate-900">{title}</h1>
        <p className="mt-1.5 text-sm leading-6 text-slate-500">{description}</p>

        <form className="mt-6 space-y-4" onSubmit={handleSubmit}>
          {/* Required Fields for Signup */}
          {isSignup && (
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <label className="block text-sm font-medium text-slate-700">
                Your name <span className="text-rose-500">*</span>
                <input
                  className={inputClassName}
                  name="name"
                  placeholder="e.g. Suresh Agarwal"
                  autoComplete="name"
                  required
                  minLength={2}
                  maxLength={100}
                />
              </label>
              <label className="block text-sm font-medium text-slate-700">
                Organization name <span className="text-rose-500">*</span>
                <input
                  className={inputClassName}
                  name="organizationName"
                  placeholder="e.g. BharatGodam Foods Ltd"
                  autoComplete="organization"
                  required
                  minLength={2}
                  maxLength={120}
                />
              </label>
            </div>
          )}

          {/* Account Credentials */}
          <div className={`grid grid-cols-1 ${isSignup ? "sm:grid-cols-2" : ""} gap-4`}>
            {isAdmin ? (
              <label className="block text-sm font-medium text-slate-700">
                Admin email
                <input
                  className={`${inputClassName} bg-slate-50`}
                  type="email"
                  value={props.adminEmail}
                  readOnly
                  aria-readonly="true"
                />
              </label>
            ) : (
              <label className="block text-sm font-medium text-slate-700">
                Email {isSignup && <span className="text-rose-500">*</span>}
                <input
                  className={inputClassName}
                  name="email"
                  type="email"
                  placeholder="name@company.com"
                  autoComplete="email"
                  required
                  maxLength={254}
                />
              </label>
            )}

            <label className="block text-sm font-medium text-slate-700">
              Password {isSignup && <span className="text-rose-500">*</span>}
              <input
                className={inputClassName}
                name="password"
                type="password"
                placeholder="••••••••"
                autoComplete={isSignup ? "new-password" : "current-password"}
                required
                minLength={isSignup ? 8 : undefined}
                maxLength={128}
              />
            </label>
          </div>

          {/* Optional Business Details Collapsible Section for Signup */}
          {isSignup && (
            <div className="mt-6 pt-2">
              <div className="rounded-2xl border border-slate-200 bg-slate-50/70 p-4 transition-all">
                <button
                  type="button"
                  onClick={() => setShowOptionalFields((prev) => !prev)}
                  className="flex w-full items-center justify-between text-left"
                >
                  <div className="flex items-center gap-2.5">
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-emerald-500/10 text-emerald-700">
                      <ShieldCheck className="h-4 w-4" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-semibold text-slate-900">
                          Business Verification & Banking Details
                        </span>
                        <span className="rounded-full bg-emerald-100 px-2 py-0.5 text-[11px] font-medium text-emerald-800">
                          Optional
                        </span>
                      </div>
                      <p className="text-xs text-slate-500">
                        {showOptionalFields
                          ? "All fields below are optional. You can also complete them later in Profile."
                          : "Add PAN, Aadhaar, GSTIN, Company Logo, Address, State & Bank Details now."}
                      </p>
                    </div>
                  </div>
                  <div className="rounded-lg p-1 text-slate-400 hover:bg-slate-200/60 hover:text-slate-600 transition">
                    {showOptionalFields ? <ChevronUp className="h-5 w-5" /> : <ChevronDown className="h-5 w-5" />}
                  </div>
                </button>

                {showOptionalFields && (
                  <div className="mt-5 space-y-5 border-t border-slate-200/80 pt-4">
                    {/* Section 1: Statutory & Tax Identification */}
                    <div>
                      <div className="mb-2.5 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-slate-600">
                        <FileText className="h-3.5 w-3.5 text-emerald-600" />
                        Statutory Identification (Optional)
                      </div>
                      <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            PAN Number
                            <input
                              className={`${inputClassName} uppercase`}
                              placeholder="ABCDE1234F"
                              value={pan}
                              onChange={handlePanChange}
                              maxLength={10}
                            />
                          </label>
                          {panError && <p className="mt-1 text-xs text-rose-600">{panError}</p>}
                        </div>

                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            Aadhaar Number
                            <input
                              className={inputClassName}
                              placeholder="1234 5678 9012"
                              value={formatAadhaarDisplay(aadhaar)}
                              onChange={handleAadhaarChange}
                              maxLength={14}
                            />
                          </label>
                          {aadhaarError && <p className="mt-1 text-xs text-rose-600">{aadhaarError}</p>}
                        </div>

                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            GSTIN
                            <input
                              className={`${inputClassName} uppercase`}
                              placeholder="27ABCDE1234F1Z5"
                              value={gstin}
                              onChange={handleGstinChange}
                              maxLength={15}
                            />
                          </label>
                          {gstinError && <p className="mt-1 text-xs text-rose-600">{gstinError}</p>}
                        </div>
                      </div>
                    </div>

                    {/* Section 2: Branding & Address */}
                    <div>
                      <div className="mb-2.5 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-slate-600">
                        <Building2 className="h-3.5 w-3.5 text-emerald-600" />
                        Company Branding & Location (Optional)
                      </div>

                      {/* Logo Upload Zone */}
                      <div className="mb-3">
                        <label className="block text-xs font-medium text-slate-600 mb-1.5">Company Logo</label>
                        {logoData ? (
                          <div className="flex items-center justify-between rounded-xl border border-emerald-200 bg-emerald-50/50 p-2.5">
                            <div className="flex items-center gap-3">
                              <img
                                src={logoData}
                                alt="Company logo preview"
                                className="h-10 w-10 rounded-lg object-contain border border-slate-200 bg-white"
                              />
                              <div>
                                <p className="text-xs font-medium text-slate-800">{logoFileName || "Uploaded logo"}</p>
                                <p className="text-[11px] text-emerald-700 flex items-center gap-1">
                                  <CheckCircle2 className="h-3 w-3" /> Ready to save with account
                                </p>
                              </div>
                            </div>
                            <button
                              type="button"
                              onClick={removeLogo}
                              className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-200 hover:text-slate-700 transition"
                              title="Remove logo"
                            >
                              <X className="h-4 w-4" />
                            </button>
                          </div>
                        ) : (
                          <div
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                            onClick={() => fileInputRef.current?.click()}
                            className={`flex cursor-pointer items-center justify-center gap-3 rounded-xl border-2 border-dashed px-4 py-3 text-center transition ${
                              isDragging
                                ? "border-emerald-500 bg-emerald-50"
                                : "border-slate-300 hover:border-slate-400 bg-white"
                            }`}
                          >
                            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100 text-slate-500">
                              <Upload className="h-4 w-4" />
                            </div>
                            <div className="text-xs text-slate-600">
                              <span className="font-semibold text-emerald-700">Click to upload</span> or drag and drop
                              logo (PNG, JPG, SVG up to 5MB)
                            </div>
                            <input
                              ref={fileInputRef}
                              type="file"
                              accept="image/*"
                              className="hidden"
                              onChange={handleFileInput}
                            />
                          </div>
                        )}
                      </div>

                      {/* Address & State */}
                      <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                        <div className="sm:col-span-2">
                          <label className="block text-xs font-medium text-slate-600">
                            Registered Address
                            <input
                              className={inputClassName}
                              placeholder="e.g. Plot 42, Sector 18, APMC Market"
                              value={address}
                              onChange={(e) => setAddress(e.target.value)}
                              maxLength={500}
                            />
                          </label>
                        </div>

                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            State
                            <select
                              className={`${inputClassName} cursor-pointer`}
                              value={selectedState}
                              onChange={(e) => setSelectedState(e.target.value)}
                            >
                              <option value="">Select State / UT</option>
                              {INDIAN_STATES.map((s) => (
                                <option key={s} value={s}>
                                  {s}
                                </option>
                              ))}
                            </select>
                          </label>
                        </div>
                      </div>
                    </div>

                    {/* Section 3: Bank Details */}
                    <div>
                      <div className="mb-2.5 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-slate-600">
                        <Landmark className="h-3.5 w-3.5 text-emerald-600" />
                        Settlement Bank Account (Optional)
                      </div>
                      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            Account Holder Name
                            <input
                              className={inputClassName}
                              placeholder="e.g. BharatGodam Foods Ltd"
                              value={accountHolderName}
                              onChange={(e) => setAccountHolderName(e.target.value)}
                              maxLength={100}
                            />
                          </label>
                        </div>

                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            Account Number
                            <input
                              className={inputClassName}
                              placeholder="e.g. 50200012345678"
                              value={accountNumber}
                              onChange={(e) => setAccountNumber(e.target.value)}
                              maxLength={35}
                            />
                          </label>
                        </div>

                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            IFSC Code
                            <input
                              className={`${inputClassName} uppercase`}
                              placeholder="e.g. HDFC0000042"
                              value={ifsc}
                              onChange={handleIfscChange}
                              maxLength={11}
                            />
                          </label>
                          {ifscError && <p className="mt-1 text-xs text-rose-600">{ifscError}</p>}
                        </div>

                        <div>
                          <label className="block text-xs font-medium text-slate-600">
                            Bank Name
                            <input
                              className={inputClassName}
                              placeholder="e.g. HDFC Bank"
                              value={bankName}
                              onChange={(e) => setBankName(e.target.value)}
                              maxLength={100}
                            />
                          </label>
                        </div>

                        <div className="sm:col-span-2">
                          <label className="block text-xs font-medium text-slate-600">
                            Branch Name
                            <input
                              className={inputClassName}
                              placeholder="e.g. Vashi APMC Commercial Branch"
                              value={branch}
                              onChange={(e) => setBranch(e.target.value)}
                              maxLength={100}
                            />
                          </label>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {error && (
            <p className="rounded-xl bg-rose-50 px-3 py-2.5 text-sm text-rose-700" role="alert">
              {error}
            </p>
          )}
          {success && (
            <p className="rounded-xl bg-emerald-50 px-3 py-2.5 text-sm text-emerald-700" role="status">
              {success}
            </p>
          )}

          <button
            className="w-full rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60 shadow-sm"
            type="submit"
            disabled={isSubmitting || (isAdmin && !props.adminEmail)}
          >
            {isSubmitting ? "Please wait..." : isSignup ? "Create account" : "Sign in"}
          </button>
          {isAdmin && !props.adminEmail && (
            <p className="text-sm text-rose-700" role="alert">
              Admin login is not configured. Set ADMIN_EMAIL in the server environment.
            </p>
          )}
        </form>

        <div className="mt-6 space-y-3 text-center text-sm text-slate-500">
          {isSignup ? (
            <p>
              Already have an account?{" "}
              <Link className="font-semibold text-emerald-700 hover:text-emerald-800" href="/signin">
                Sign in
              </Link>
            </p>
          ) : (
            <p>
              {isAdmin ? "Not an admin?" : "New to BharatGodam?"}{" "}
              <Link
                className="font-semibold text-emerald-700 hover:text-emerald-800"
                href={isAdmin ? "/signin" : "/signup"}
              >
                {isAdmin ? "User sign in" : "Create an account"}
              </Link>
            </p>
          )}
          {!isSignup && !isAdmin && (
            <p>
              <Link className="text-slate-500 underline underline-offset-4 hover:text-slate-700" href="/admin/login">
                Admin login
              </Link>
            </p>
          )}
        </div>
      </section>
    </main>
  );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import {
  Search,
  Filter,
  Bookmark,
  BookmarkCheck,
  Phone,
  Mail,
  MapPin,
  Building2,
  ShieldCheck,
  Star,
  MessageSquare,
  Plus,
  RefreshCw,
  Eye,
  SlidersHorizontal,
  X,
  Send,
  CheckCircle2,
  AlertCircle,
  Pencil,
  Trash2,
} from "lucide-react";

export interface BuyerItem {
  id: string;
  buyerCode: string;
  companyName: string;
  contactPerson: string;
  designation: string;
  email: string;
  phone: string;
  whatsapp: string;
  city: string;
  state: string;
  businessType: string;
  commodities: string[];
  annualVolume: string;
  minQuantity: number;
  maxQuantity: number;
  unit: string;
  paymentTerms: string;
  gstin: string;
  verified: boolean;
  rating: number;
  status?: "Active" | "Inactive" | string;
  description: string;
  yearEstablished: number | null;
  isSaved: boolean;
  createdAt?: string;
}

export function BuyerDirectory() {
  const [buyers, setBuyers] = useState<BuyerItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [isPending, startTransition] = useTransition();

  // Filter state
  const [search, setSearch] = useState("");
  const [selectedCommodity, setSelectedCommodity] = useState("all");
  const [selectedState, setSelectedState] = useState("all");
  const [selectedBusinessType, setSelectedBusinessType] = useState("all");
  const [minQty, setMinQty] = useState("");
  const [maxQty, setMaxQty] = useState("");
  const [savedOnly, setSavedOnly] = useState(false);

  // Available filter options from backend
  const [availableCommodities, setAvailableCommodities] = useState<string[]>([]);
  const [availableStates, setAvailableStates] = useState<string[]>([]);
  const [availableBusinessTypes, setAvailableBusinessTypes] = useState<string[]>([]);

  // Modals state
  const [profileModalBuyer, setProfileModalBuyer] = useState<BuyerItem | null>(null);
  const [contactModalBuyer, setContactModalBuyer] = useState<BuyerItem | null>(null);
  const [newBuyerModalOpen, setNewBuyerModalOpen] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [canAddBuyer, setCanAddBuyer] = useState(false);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ type: "success" | "error"; message: string } | null>(null);

  // Contact form state
  const [contactForm, setContactForm] = useState({
    subject: "",
    message: "",
    offeredCommodity: "",
    proposedQuantity: "",
    proposedPrice: "",
    senderPhone: "",
    senderEmail: "",
  });
  const [contactSubmitting, setContactSubmitting] = useState(false);

  // New buyer form state
  const [newBuyerForm, setNewBuyerForm] = useState({
    companyName: "",
    contactPerson: "",
    designation: "Procurement Manager",
    email: "",
    phone: "",
    city: "",
    state: "",
    businessType: "Wholesaler",
    commodities: "",
    annualVolume: "1,000 MT",
    minQuantity: "10",
    maxQuantity: "100",
    unit: "MT",
    paymentTerms: "Immediate RTGS upon delivery",
    gstin: "",
    description: "",
  });
  const [newBuyerSubmitting, setNewBuyerSubmitting] = useState(false);

  // Edit buyer form state (Admin only)
  const [editModalBuyer, setEditModalBuyer] = useState<BuyerItem | null>(null);
  const [editForm, setEditForm] = useState({
    companyName: "",
    contactPerson: "",
    designation: "",
    email: "",
    phone: "",
    city: "",
    state: "",
    businessType: "Wholesaler",
    commodities: "",
    annualVolume: "",
    minQuantity: "0",
    maxQuantity: "0",
    unit: "MT",
    paymentTerms: "",
    gstin: "",
    status: "Active" as "Active" | "Inactive",
    description: "",
  });
  const [editSubmitting, setEditSubmitting] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const fetchBuyers = async (targetPage = page) => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: String(targetPage),
        limit: "12",
      });
      if (search.trim()) params.set("search", search.trim());
      if (selectedCommodity !== "all") params.set("commodity", selectedCommodity);
      if (selectedState !== "all") params.set("state", selectedState);
      if (selectedBusinessType !== "all") params.set("businessType", selectedBusinessType);
      if (minQty) params.set("minQuantity", minQty);
      if (maxQty) params.set("maxQuantity", maxQty);
      if (savedOnly) params.set("savedOnly", "true");

      const res = await fetch(`/api/buyers?${params.toString()}`);
      if (!res.ok) throw new Error("Failed to load buyers");
      const data = await res.json();
      setBuyers(data.buyers || []);
      setTotal(data.total || 0);
      setPages(data.pages || 1);
      setPage(data.page || 1);
      if (data.availableCommodities) setAvailableCommodities(data.availableCommodities);
      if (data.availableStates) setAvailableStates(data.availableStates);
      if (data.availableBusinessTypes) setAvailableBusinessTypes(data.availableBusinessTypes);
      // Create buyer functionality in marketplace is only for admin (Admin login).
      // Regular user login accounts can only view buyers and buyer details.
      const isSystemAdmin = Boolean(
        data.currentUser?.id === "admin" ||
        data.currentUser?.role === "Super Admin" ||
        data.currentUser?.isSystemAdmin ||
        data.currentUser?.isPlatformAdmin
      );
      setIsAdmin(isSystemAdmin);
      setCanAddBuyer(isSystemAdmin);
    } catch (err) {
      console.error(err);
      setFeedback({ type: "error", message: "Failed to load buyers directory. Please try again." });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchBuyers(1);
    }, 250);
    return () => clearTimeout(timer);
  }, [search, selectedCommodity, selectedState, selectedBusinessType, minQty, maxQty, savedOnly]);

  const toggleSaveBuyer = async (buyer: BuyerItem) => {
    setSavingId(buyer.id);
    try {
      const res = await fetch(`/api/buyers/${buyer.id}/save`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      });
      if (!res.ok) throw new Error("Failed to save buyer");
      const data = await res.json();
      setBuyers((prev) =>
        prev.map((b) => (b.id === buyer.id ? { ...b, isSaved: data.isSaved } : b)),
      );
      setFeedback({
        type: "success",
        message: data.isSaved
          ? `Added ${buyer.companyName} to saved buyers`
          : `Removed ${buyer.companyName} from saved buyers`,
      });
    } catch {
      setFeedback({ type: "error", message: "Failed to update saved status" });
    } finally {
      setSavingId(null);
    }
  };

  const handleContactSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!contactModalBuyer) return;
    setContactSubmitting(true);
    try {
      const res = await fetch(`/api/buyers/${contactModalBuyer.id}/contact`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...contactForm,
          proposedQuantity: contactForm.proposedQuantity ? Number(contactForm.proposedQuantity) : undefined,
          proposedPrice: contactForm.proposedPrice ? Number(contactForm.proposedPrice) : undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to send message");
      setFeedback({ type: "success", message: data.message });
      setContactModalBuyer(null);
      setContactForm({
        subject: "",
        message: "",
        offeredCommodity: "",
        proposedQuantity: "",
        proposedPrice: "",
        senderPhone: "",
        senderEmail: "",
      });
    } catch (err: unknown) {
      setFeedback({ type: "error", message: err instanceof Error ? err.message : "Failed to contact buyer" });
    } finally {
      setContactSubmitting(false);
    }
  };

  const handleNewBuyerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canAddBuyer) {
      setFeedback({ type: "error", message: "Forbidden: Only administrators can add new buyers." });
      setNewBuyerModalOpen(false);
      return;
    }
    setNewBuyerSubmitting(true);
    try {
      const commodityList = newBuyerForm.commodities
        .split(",")
        .map((c) => c.trim())
        .filter(Boolean);

      const res = await fetch("/api/buyers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...newBuyerForm,
          commodities: commodityList.length > 0 ? commodityList : ["General Produce"],
          minQuantity: Number(newBuyerForm.minQuantity) || 0,
          maxQuantity: Number(newBuyerForm.maxQuantity) || 0,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to create buyer profile");
      setFeedback({ type: "success", message: "New buyer profile added successfully!" });
      setNewBuyerModalOpen(false);
      setNewBuyerForm({
        companyName: "",
        contactPerson: "",
        designation: "Procurement Manager",
        email: "",
        phone: "",
        city: "",
        state: "",
        businessType: "Wholesaler",
        commodities: "",
        annualVolume: "1,000 MT",
        minQuantity: "10",
        maxQuantity: "100",
        unit: "MT",
        paymentTerms: "Immediate RTGS upon delivery",
        gstin: "",
        description: "",
      });
      fetchBuyers(1);
    } catch (err: unknown) {
      setFeedback({ type: "error", message: err instanceof Error ? err.message : "Failed to create buyer" });
    } finally {
      setNewBuyerSubmitting(false);
    }
  };

  const openEditModal = (buyer: BuyerItem) => {
    if (!isAdmin) return;
    setEditModalBuyer(buyer);
    setEditForm({
      companyName: buyer.companyName,
      contactPerson: buyer.contactPerson,
      designation: buyer.designation || "",
      email: buyer.email || "",
      phone: buyer.phone || "",
      city: buyer.city,
      state: buyer.state,
      businessType: buyer.businessType || "Wholesaler",
      commodities: (buyer.commodities || []).join(", "),
      annualVolume: buyer.annualVolume || "",
      minQuantity: String(buyer.minQuantity ?? 0),
      maxQuantity: String(buyer.maxQuantity ?? 0),
      unit: buyer.unit || "MT",
      paymentTerms: buyer.paymentTerms || "",
      gstin: buyer.gstin || "",
      status: (buyer.status as "Active" | "Inactive") || "Active",
      description: buyer.description || "",
    });
  };

  const handleEditBuyerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAdmin || !editModalBuyer) {
      setFeedback({ type: "error", message: "Forbidden: Only administrators can edit buyers." });
      setEditModalBuyer(null);
      return;
    }
    setEditSubmitting(true);
    try {
      const commodityList = editForm.commodities
        .split(",")
        .map((c) => c.trim())
        .filter(Boolean);

      const res = await fetch(`/api/buyers/${editModalBuyer.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...editForm,
          commodities: commodityList.length > 0 ? commodityList : ["General Produce"],
          minQuantity: Number(editForm.minQuantity) || 0,
          maxQuantity: Number(editForm.maxQuantity) || 0,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to update buyer");
      setFeedback({ type: "success", message: "Buyer profile updated successfully!" });
      setEditModalBuyer(null);
      if (profileModalBuyer?.id === editModalBuyer.id && data.buyer) {
        setProfileModalBuyer({ ...profileModalBuyer, ...data.buyer });
      }
      fetchBuyers(page);
    } catch (err: unknown) {
      setFeedback({ type: "error", message: err instanceof Error ? err.message : "Failed to update buyer" });
    } finally {
      setEditSubmitting(false);
    }
  };

  const handleDeleteBuyer = async (buyerId: string) => {
    if (!isAdmin) return;
    if (!window.confirm("Are you sure you want to remove this buyer profile? This action cannot be undone.")) return;
    setDeleting(true);
    try {
      const res = await fetch(`/api/buyers/${buyerId}`, { method: "DELETE" });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to delete buyer");
      setFeedback({ type: "success", message: "Buyer profile deleted successfully" });
      setEditModalBuyer(null);
      setProfileModalBuyer(null);
      fetchBuyers(page);
    } catch (err: unknown) {
      setFeedback({ type: "error", message: err instanceof Error ? err.message : "Failed to delete buyer" });
    } finally {
      setDeleting(false);
    }
  };

  const clearFilters = () => {
    setSearch("");
    setSelectedCommodity("all");
    setSelectedState("all");
    setSelectedBusinessType("all");
    setMinQty("");
    setMaxQty("");
    setSavedOnly(false);
  };

  const hasActiveFilters =
    search.trim() !== "" ||
    selectedCommodity !== "all" ||
    selectedState !== "all" ||
    selectedBusinessType !== "all" ||
    minQty !== "" ||
    maxQty !== "" ||
    savedOnly;

  return (
    <div className="space-y-6">
      {/* Top Banner / Heading */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold tracking-tight text-slate-900">Find Buyers</h1>
            <span className="rounded-full bg-emerald-100 px-2.5 py-0.5 text-xs font-semibold text-emerald-800">
              Verified Directory
            </span>
          </div>
          <p className="mt-1 text-sm text-slate-600">
            Discover verified commodity buyers, food processors, and grain millers across India.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={() => setSavedOnly(!savedOnly)}
            className={`inline-flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-medium transition shadow-sm ${
              savedOnly
                ? "border-amber-400 bg-amber-50 text-amber-800 hover:bg-amber-100"
                : "border-slate-300 bg-white text-slate-700 hover:bg-slate-50"
            }`}
          >
            {savedOnly ? <BookmarkCheck className="h-4 w-4 text-amber-600" /> : <Bookmark className="h-4 w-4 text-slate-500" />}
            <span>{savedOnly ? "Showing Saved" : "Saved Buyers"}</span>
          </button>
          {canAddBuyer && (
            <button
              type="button"
              id="add-buyer-button"
              onClick={() => setNewBuyerModalOpen(true)}
              className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white shadow-sm hover:bg-blue-700 transition"
            >
              <Plus className="h-4 w-4" />
              Add Buyer Profile
            </button>
          )}
        </div>
      </div>

      {/* Notification Toast */}
      {feedback && (
        <div
          className={`flex items-center justify-between rounded-xl p-4 text-sm shadow-sm transition ${
            feedback.type === "success"
              ? "bg-emerald-50 text-emerald-900 border border-emerald-200"
              : "bg-red-50 text-red-900 border border-red-200"
          }`}
        >
          <div className="flex items-center gap-2">
            {feedback.type === "success" ? (
              <CheckCircle2 className="h-5 w-5 text-emerald-600 shrink-0" />
            ) : (
              <AlertCircle className="h-5 w-5 text-red-600 shrink-0" />
            )}
            <span>{feedback.message}</span>
          </div>
          <button
            type="button"
            onClick={() => setFeedback(null)}
            className="rounded p-1 hover:bg-black/5"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* KPI Cards */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
          <p className="text-xs font-medium uppercase tracking-wider text-slate-500">Total Buyers</p>
          <p className="mt-2 text-2xl font-bold text-slate-900">{total}</p>
          <p className="mt-1 text-xs text-slate-500">Active purchasing profiles</p>
        </div>
        <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
          <p className="text-xs font-medium uppercase tracking-wider text-slate-500">Commodities</p>
          <p className="mt-2 text-2xl font-bold text-emerald-600">{availableCommodities.length || 8}</p>
          <p className="mt-1 text-xs text-slate-500">Across major grain & spice categories</p>
        </div>
        <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
          <p className="text-xs font-medium uppercase tracking-wider text-slate-500">States Covered</p>
          <p className="mt-2 text-2xl font-bold text-blue-600">{availableStates.length || 6}</p>
          <p className="mt-1 text-xs text-slate-500">Pan-India distribution</p>
        </div>
        <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
          <p className="text-xs font-medium uppercase tracking-wider text-slate-500">Verified Rate</p>
          <p className="mt-2 text-2xl font-bold text-emerald-700">100%</p>
          <p className="mt-1 text-xs text-slate-500">KYC & GST verified traders</p>
        </div>
      </div>

      {/* Filter and Search Box */}
      <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm space-y-4">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
          {/* Main search input */}
          <div className="relative flex-1">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by company name, contact person, commodity, city, or code..."
              className="w-full rounded-xl border border-slate-300 bg-slate-50 pl-10 pr-4 py-2.5 text-sm outline-none transition focus:border-emerald-500 focus:bg-white focus:ring-2 focus:ring-emerald-500/20"
            />
            {search && (
              <button
                type="button"
                onClick={() => setSearch("")}
                className="absolute right-3 top-1/2 -translate-y-1/2 rounded p-1 text-slate-400 hover:text-slate-600"
              >
                <X className="h-3.5 w-3.5" />
