  requiredDeliveryDate: string;
  description: string;
  status: "Pending" | "Approved" | "Open" | "In Progress" | "Closed" | "Offers Received" | "Accepted" | "Rejected" | "Fulfilled" | "Cancelled";
  offersCount: number;
  acceptedOfferId: string | null;
  buyerId: string;
  buyerName: string;
  buyerCompany: string;
  buyerEmail?: string;
  buyerPhone?: string;
  isMine: boolean;
  adminStatus?: "Pending" | "Approved";
  myOffer?: {
    id: string;
    offerId: string;
    offeredPrice: number;
    availableQuantity: number;
    deliveryTerms: string;
    status: "Pending" | "Accepted" | "Rejected" | "Withdrawn";
    createdAt: string;
  } | null;
  createdAt: string;
}

export interface OfferItem {
  id: string;
  offerId: string;
  sellerId: string;
  sellerName: string;
  sellerCompany: string;
  sellerEmail?: string;
  sellerPhone?: string;
  offeredPrice: number;
  availableQuantity: number;
  unit: string;
  deliveryTerms: string;
  validTill?: string | null;
  remarks?: string;
  status: "Pending" | "Accepted" | "Rejected" | "Withdrawn";
  createdAt: string;
}

export function BuyingRequestsWorkspace() {
  const [activeTab, setActiveTab] = useState<"all" | "my-requests" | "open-market" | "my-offers">("all");
  const [requests, setRequests] = useState<BuyingRequestItem[]>([]);
