"use client";

import { useEffect, useState } from "react";
import {
  AlertCircle,
  CheckCircle2,
  CreditCard,
  DollarSign,
  FileText,
  Loader2,
  Sparkles,
  X,
} from "lucide-react";

export interface AvailableCreditNote {
  id: string;
  creditNoteNumber: string;
  customerId: string;
  customerName: string;
  creditNoteDate: string;
  referenceNumber?: string;
  subject?: string;
  total: number;
  creditedAmount: number;
  balanceRemaining: number;
  status: string;
}

interface ApplyCreditNotesModalProps {
  isOpen: boolean;
  onClose: () => void;
  invoiceId: string;
  invoiceNumber: string;
  customerName: string;
  balanceDue: number;
  onSuccess: () => void;
}

export function ApplyCreditNotesModal({
  isOpen,
  onClose,
  invoiceId,
  invoiceNumber,
  customerName,
  balanceDue,
  onSuccess,
}: ApplyCreditNotesModalProps) {
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [availableCredits, setAvailableCredits] = useState<AvailableCreditNote[]>([]);
  const [creditAmounts, setCreditAmounts] = useState<Record<string, string>>({});
  const [invoiceDetails, setInvoiceDetails] = useState<{
    balanceDue: number;
    total: number;
    amountPaid: number;
    creditedAmount: number;
  }>({
    balanceDue,
    total: balanceDue,
    amountPaid: 0,
    creditedAmount: 0,
  });

  useEffect(() => {
    if (!isOpen || !invoiceId) return;

    let isMounted = true;
    setLoading(true);
    setError(null);
    setCreditAmounts({});

    fetch(`/api/sales/invoices/${invoiceId}/credit-notes`)
      .then(async (res) => {
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || "Failed to load credit notes for invoice.");
        return data;
      })
      .then((data) => {
        if (!isMounted) return;
        setAvailableCredits(data.availableCredits || []);
        if (data.invoice) {
          setInvoiceDetails({
            balanceDue: Number(data.invoice.balanceDue ?? balanceDue),
            total: Number(data.invoice.total || 0),
            amountPaid: Number(data.invoice.amountPaid || 0),
            creditedAmount: Number(data.invoice.creditedAmount || 0),
          });
        }
        // If exactly one credit note is available, pre-fill its max applicable amount
        if (Array.isArray(data.availableCredits) && data.availableCredits.length === 1) {
          const single = data.availableCredits[0];
          const curBal = Number(data.invoice?.balanceDue ?? balanceDue);
          const maxApp = Math.min(single.balanceRemaining, curBal);
          if (maxApp > 0) {
            setCreditAmounts({ [single.id]: maxApp.toFixed(2) });
          }
        }
      })
      .catch((err) => {
        if (!isMounted) return;
        setError(err.message || "Failed to load available credit notes.");
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, [isOpen, invoiceId, balanceDue]);

  if (!isOpen) return null;

  const totalCreditApplying = Object.values(creditAmounts).reduce((sum, val) => {
    const num = parseFloat(val);
    return sum + (isNaN(num) || num < 0 ? 0 : num);
  }, 0);
  const roundedApplying = Math.round(totalCreditApplying * 100) / 100;
  const currentInvoiceDue = invoiceDetails.balanceDue;
  const remainingDueAfterCredit = Math.max(
    0,
    Math.round((currentInvoiceDue - roundedApplying) * 100) / 100,
  );
  const totalAvailableCredit = availableCredits.reduce(
    (sum, c) => sum + c.balanceRemaining,
    0,
  );

  const handleAmountChange = (credId: string, val: string, maxCreditAvailable: number) => {
    setError(null);
    if (val === "") {
      setCreditAmounts((prev) => ({ ...prev, [credId]: "" }));
      return;
    }

    const num = parseFloat(val);
    if (isNaN(num) || num < 0) {
      setCreditAmounts((prev) => ({ ...prev, [credId]: "0" }));
      return;
    }

    if (num > maxCreditAvailable) {
      setError(
        `Amount cannot exceed the available credit balance of ₹${maxCreditAvailable.toFixed(2)}.`,
      );
      setCreditAmounts((prev) => ({ ...prev, [credId]: maxCreditAvailable.toFixed(2) }));
      return;
    }

    setCreditAmounts((prev) => ({ ...prev, [credId]: val }));
  };

  const handleSetMaxForCredit = (credId: string, maxCreditAvailable: number) => {
    setError(null);
    const otherAllocations = Object.entries(creditAmounts)
      .filter(([id]) => id !== credId)
      .reduce((sum, [, amt]) => {
        const num = parseFloat(amt);
        return sum + (isNaN(num) || num < 0 ? 0 : num);
      }, 0);

    const remainingDueForThis = Math.max(0, currentInvoiceDue - otherAllocations);
    const maxCanApply = Math.min(maxCreditAvailable, remainingDueForThis);
    setCreditAmounts((prev) => ({
      ...prev,
      [credId]: maxCanApply > 0 ? maxCanApply.toFixed(2) : "0",
    }));
  };

  const handleApplyAllAvailable = () => {
    setError(null);
    let remainingDue = currentInvoiceDue;
    const newAmounts: Record<string, string> = {};

    for (const cred of availableCredits) {
      if (remainingDue <= 0) {
        newAmounts[cred.id] = "";
        continue;
      }
      const canApply = Math.min(cred.balanceRemaining, remainingDue);
      const rounded = Math.round(canApply * 100) / 100;
      newAmounts[cred.id] = rounded > 0 ? rounded.toFixed(2) : "";
      remainingDue = Math.max(0, Math.round((remainingDue - rounded) * 100) / 100);
    }

    setCreditAmounts(newAmounts);
  };

  const handleClearAll = () => {
    setCreditAmounts({});
    setError(null);
  };

  const handleSubmit = async () => {
    setError(null);

    const validApps = Object.entries(creditAmounts)
      .map(([creditNoteId, amtStr]) => ({
        creditNoteId,
        amount: Math.round((parseFloat(amtStr) || 0) * 100) / 100,
      }))
      .filter((app) => app.amount > 0);

    if (validApps.length === 0) {
      setError("Please specify at least one valid credit note amount to apply.");
      return;
    }

    if (roundedApplying > currentInvoiceDue + 0.01) {
      setError(
        `Total credit applied (₹${roundedApplying.toFixed(2)}) exceeds invoice's balance due (₹${currentInvoiceDue.toFixed(2)}).`,
      );
      return;
    }

    for (const app of validApps) {
      const targetCred = availableCredits.find((c) => c.id === app.creditNoteId);
      if (targetCred && app.amount > targetCred.balanceRemaining + 0.01) {
        setError(
          `Amount for Credit Note #${targetCred.creditNoteNumber} exceeds available balance (₹${targetCred.balanceRemaining.toFixed(2)}).`,
        );
        return;
      }
    }

    setSubmitting(true);
    try {
      const res = await fetch(`/api/sales/invoices/${invoiceId}/apply-credits`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ credits: validApps }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to apply credit notes to invoice.");
      }

      onSuccess();
      onClose();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to apply credit notes.";
      setError(msg);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-xs animate-in fade-in duration-150"
      role="dialog"
      aria-modal="true"
    >
      <div className="relative flex max-h-[92vh] w-full max-w-4xl flex-col rounded-2xl border border-slate-200 bg-white shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-200 px-6 py-4">
          <div className="flex items-center gap-2.5">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-purple-50 text-purple-600">
              <CreditCard className="h-5 w-5" />
            </div>
            <div>
              <h3 className="text-base sm:text-lg font-bold text-slate-900">
                Apply Credit Notes to Invoice #{invoiceNumber}
              </h3>
              <p className="text-xs text-slate-500">
                Customer: <span className="font-semibold text-slate-700">{customerName}</span>
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition cursor-pointer"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Summary Metric Ribbon */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 bg-slate-50 border-b border-slate-200 px-6 py-3 text-xs">
          <div>
            <span className="text-slate-500 block text-[11px] uppercase tracking-wider font-medium">
              Invoice Total
            </span>
            <span className="font-bold text-slate-900 text-sm sm:text-base font-mono">
              ₹{invoiceDetails.total.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </span>
          </div>
          <div>
            <span className="text-slate-500 block text-[11px] uppercase tracking-wider font-medium">
              Payment Due
            </span>
            <span className="font-bold text-amber-700 text-sm sm:text-base font-mono">
              ₹{currentInvoiceDue.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </span>
          </div>
          <div>
            <span className="text-slate-500 block text-[11px] uppercase tracking-wider font-medium">
              Credit Applying
            </span>
            <span
              className={`font-bold text-sm sm:text-base font-mono ${
                roundedApplying > currentInvoiceDue ? "text-rose-600" : "text-purple-700"
              }`}
            >
              ₹{roundedApplying.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </span>
          </div>
          <div>
            <span className="text-slate-500 block text-[11px] uppercase tracking-wider font-medium">
              Remaining Due
            </span>
            <span className="font-bold text-emerald-600 text-sm sm:text-base font-mono">
              ₹{remainingDueAfterCredit.toLocaleString("en-IN", { minimumFractionDigits: 2 })}
            </span>
          </div>
        </div>

        {/* Error Notice */}
        {error && (
          <div className="mx-6 mt-4 flex items-center gap-2 rounded-xl border border-rose-200 bg-rose-50 p-3 text-xs text-rose-700">
            <AlertCircle className="h-4 w-4 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {/* Content Body */}
        <div className="flex-1 overflow-y-auto px-6 py-4">
          {loading ? (
            <div className="flex flex-col items-center justify-center py-12 text-slate-500">
              <Loader2 className="h-8 w-8 animate-spin text-purple-600 mb-2" />
              <p className="text-xs">Loading available customer credit notes…</p>
            </div>
          ) : availableCredits.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-purple-50 text-purple-600 mb-3">
                <CreditCard className="h-6 w-6" />
              </div>
              <p className="text-sm font-semibold text-slate-700">
                No Available Credit Notes Found
              </p>
              <p className="text-xs text-slate-500 mt-1 max-w-sm">
                There are no open or partially applied credit notes with an available balance for{" "}
                <span className="font-medium text-slate-700">{customerName}</span>.
              </p>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-slate-600">
                <span>
                  Customer has{" "}
                  <strong className="text-purple-700 font-mono">
                    ₹{totalAvailableCredit.toFixed(2)}
                  </strong>{" "}
                  in available credit notes. Enter amounts to apply:
                </span>
                <div className="flex items-center gap-3">
                  <button
                    type="button"
                    onClick={handleApplyAllAvailable}
                    className="inline-flex items-center gap-1 font-semibold text-purple-700 hover:text-purple-800 hover:underline cursor-pointer"
                  >
                    <Sparkles className="h-3.5 w-3.5" />
                    Apply All Available
                  </button>
                  <span>•</span>
                  <button
                    type="button"
                    onClick={handleClearAll}
                    className="font-medium text-slate-500 hover:text-slate-700 underline cursor-pointer"
                  >
                    Clear all
                  </button>
                </div>
              </div>

              <div className="overflow-x-auto rounded-xl border border-slate-200">
                <table className="min-w-full divide-y divide-slate-200 text-left text-xs">
                  <thead className="bg-slate-50 text-slate-600 font-semibold uppercase tracking-wider text-[11px]">
                    <tr>
                      <th className="px-3 py-2.5">Credit Note#</th>
                      <th className="px-3 py-2.5">Date</th>
                      <th className="px-3 py-2.5 text-right">Total Amount</th>
                      <th className="px-3 py-2.5 text-right">Already Applied</th>
                      <th className="px-3 py-2.5 text-right">Available Balance</th>
                      <th className="px-3 py-2.5 text-right min-w-[160px]">Amount to Apply</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 bg-white">
                    {availableCredits.map((cred) => {
                      const curVal = creditAmounts[cred.id] || "";
                      const curNum = parseFloat(curVal) || 0;
                      const hasAmt = curNum > 0;

                      return (
                        <tr
                          key={cred.id}
                          className={`transition ${hasAmt ? "bg-purple-50/40" : "hover:bg-slate-50"}`}
                        >
                          <td className="px-3 py-3 font-semibold text-slate-900">
                            {cred.creditNoteNumber}
                            {cred.subject && (
                              <p className="text-[11px] text-slate-400 font-normal truncate max-w-[160px]">
                                {cred.subject}
                              </p>
                            )}
                          </td>
                          <td className="px-3 py-3 text-slate-600 whitespace-nowrap">
                            {cred.creditNoteDate || "—"}
                          </td>
                          <td className="px-3 py-3 text-right font-medium text-slate-900 font-mono">
                            ₹{cred.total.toFixed(2)}
                          </td>
                          <td className="px-3 py-3 text-right text-slate-600 font-mono">
                            ₹{cred.creditedAmount.toFixed(2)}
                          </td>
                          <td className="px-3 py-3 text-right font-bold text-emerald-600 font-mono">
                            ₹{cred.balanceRemaining.toFixed(2)}
                          </td>
                          <td className="px-3 py-3 text-right">
                            <div className="flex items-center justify-end gap-1.5">
                              <div className="relative w-28">
                                <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 text-xs">
                                  ₹
                                </span>
                                <input
                                  type="number"
                                  step="any"
                                  min="0"
                                  max={cred.balanceRemaining}
                                  value={curVal}
                                  onChange={(e) =>
                                    handleAmountChange(cred.id, e.target.value, cred.balanceRemaining)
                                  }
                                  placeholder="0.00"
                                  className="w-full rounded-lg border border-slate-300 bg-white pl-6 pr-2 py-1.5 text-right font-mono text-xs text-slate-900 outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500"
                                />
                              </div>
                              <button
                                type="button"
                                onClick={() =>
                                  handleSetMaxForCredit(cred.id, cred.balanceRemaining)
                                }
                                className="rounded-md border border-slate-200 bg-slate-50 px-2 py-1.5 text-[11px] font-semibold text-purple-700 hover:bg-purple-50 hover:border-purple-200 transition cursor-pointer shrink-0"
                                title="Apply maximum allowable amount from this credit note"
                              >
                                Max
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Modal Actions */}
        <div className="flex items-center justify-end gap-3 border-t border-slate-200 px-6 py-4 bg-slate-50/50">
          <button
            type="button"
            onClick={onClose}
            disabled={submitting}
            className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-xs sm:text-sm font-semibold text-slate-700 hover:bg-slate-50 transition cursor-pointer"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={
              submitting ||
              loading ||
              availableCredits.length === 0 ||
              roundedApplying <= 0 ||
              roundedApplying > currentInvoiceDue
            }
            className="inline-flex items-center justify-center rounded-lg bg-purple-600 px-5 py-2 text-xs sm:text-sm font-semibold text-white shadow-xs hover:bg-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500/20 disabled:opacity-50 transition cursor-pointer"
          >
            {submitting ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Applying Credit…
              </>
            ) : (
              `Apply Credit (₹${roundedApplying.toFixed(2)})`
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  ArrowLeft,
  Calculator,
  Calendar,
  CheckCircle2,
  FileText,
  Loader2,
  Package,
  Plus,
  Settings,
  Trash2,
  User,
  UserPlus,
  X,
} from "lucide-react";
import {
  calculateInvoiceTotals,
  formatCurrency,
  numberToIndianWords,
} from "@/lib/invoice-utils";
import {
  GST_RATE_OPTIONS,
  INDIAN_STATES,
  PAYMENT_TERMS_OPTIONS,
  type CustomerOption,
  type InvoiceItemData,
  type InvoiceRecord,
  type InvoiceSettingsData,
  type ItemOption,
} from "./invoice-types";
import { QuickCustomerModal } from "./quick-customer-modal";
import { QuickItemModal } from "./quick-item-modal";
import { ConfigureInvoiceNumberModal } from "./configure-invoice-number-modal";
import { formatInvoiceNumber } from "@/lib/invoice-numbering";
import {
  calculateDueDateFromPaymentTerms,
  type PaymentTermItem,
} from "@/lib/payment-terms";

interface InvoiceFormProps {
  initialData?: InvoiceRecord;
  isEditing?: boolean;
}

interface FormItemRow {
  rowId: string;
  itemId?: string;
  name: string;
  description: string;
  hsnCode: string;
  unit: string;
  quantity: number;
  rate: number;
  discount: number;
  discountType: "percent" | "amount";
  taxRate: number;
}

export function InvoiceForm({
  initialData,
  isEditing = false,
}: InvoiceFormProps) {
  const router = useRouter();

  // Master Data
  const [customers, setCustomers] = useState<CustomerOption[]>([]);
  const [availableItems, setAvailableItems] = useState<ItemOption[]>([]);
  const [isLoadingMasterData, setIsLoadingMasterData] = useState(true);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showItemModal, setShowItemModal] = useState(false);
  const [showNumberConfigModal, setShowNumberConfigModal] = useState(false);
  const [activeItemRowId, setActiveItemRowId] = useState<string | null>(null);

  // Settings & Numbering State
  const [invoiceSettings, setInvoiceSettings] = useState<InvoiceSettingsData | null>(null);
  const [autoGenerateNumbering, setAutoGenerateNumbering] = useState(true);

  // Form State
  const [selectedCustomerId, setSelectedCustomerId] = useState(() => {
    if (initialData?.customerId) return initialData.customerId;
    if (typeof window !== "undefined") {
      return new URLSearchParams(window.location.search).get("customerId") || "";
    }
    return "";
  });
  const [invoiceNumber, setInvoiceNumber] = useState(
    initialData?.number || "",
  );
  const [referenceNumber, setReferenceNumber] = useState(
    initialData?.referenceNumber || "",
  );
  const [invoiceDate, setInvoiceDate] = useState(() => {
    if (initialData?.issueDate) {
      return new Date(initialData.issueDate).toISOString().split("T")[0];
    }
    return new Date().toISOString().split("T")[0];
  });
  const [paymentTerms, setPaymentTerms] = useState(
    initialData?.paymentTerms || "Due on Receipt",
  );
  const [dueDate, setDueDate] = useState(() => {
    if (initialData?.dueDate) {
      return new Date(initialData.dueDate).toISOString().split("T")[0];
    }
    return new Date().toISOString().split("T")[0];
  });
  const [placeOfSupply, setPlaceOfSupply] = useState(
    initialData?.placeOfSupply || "Maharashtra",
  );
  const [salesperson, setSalesperson] = useState(
    initialData?.salesperson || "",
  );
  const [subject, setSubject] = useState(initialData?.subject || "");

  // Line items state
  const [rows, setRows] = useState<FormItemRow[]>(() => {
    if (initialData?.items && initialData.items.length > 0) {
      return initialData.items.map((item, idx) => ({
        rowId: `row-${idx + 1}`,
        itemId: item.itemId,
        name: item.name,
        description: item.description || "",
        hsnCode: item.hsnCode || "",
        unit: item.unit || "pcs",
        quantity: item.quantity || 1,
        rate: item.rate || 0,
        discount: item.discount || 0,
        discountType: item.discountType || "percent",
        taxRate: item.taxRate || 18,
      }));
    }
    return [
      {
        rowId: "row-1",
        name: "",
        description: "",
        hsnCode: "",
        unit: "pcs",
        quantity: 1,
        rate: 0,
        discount: 0,
        discountType: "percent",
        taxRate: 18,
      },
    ];
  });

  // Invoice-level adjustments
  const [invoiceDiscount, setInvoiceDiscount] = useState<string>(
    initialData ? String(initialData.discount || "") : "",
  );
  const [invoiceDiscountType, setInvoiceDiscountType] = useState<
    "percent" | "amount"
  >(initialData?.discountType || "percent");
  const [shippingCharges, setShippingCharges] = useState<string>(
    initialData ? String(initialData.shippingCharges || "") : "",
  );
  const [adjustment, setAdjustment] = useState<string>(
    initialData ? String(initialData.adjustment || "") : "",
  );

  // Notes & terms
  const [customerNotes, setCustomerNotes] = useState(
    initialData?.customerNotes || "Thank you for your business. Please reach out with any questions.",
  );
  const [termsAndConditions, setTermsAndConditions] = useState(
    initialData?.termsAndConditions ||
      "1. Payment is due as per terms specified above.\n2. Please mention the invoice number in your remittance.\n3. Goods once sold will not be returned without authorization.",
  );

  // Submission State
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load Customers & Items
  useEffect(() => {
    let isMounted = true;
    Promise.all([
      fetch("/api/sales?section=customers").then((r) => (r.ok ? r.json() : { customers: [] })),
      fetch("/api/items").then((r) => (r.ok ? r.json() : { items: [] })),
      fetch("/api/sales/invoices/settings").then((r) => (r.ok ? r.json() : { settings: null })),
    ])
      .then(([custData, itemsData, settingsData]) => {
        if (!isMounted) return;
        const mappedCusts: CustomerOption[] = (custData.customers || []).map((c: any) => ({
          id: c.id,
          name: c.name,
          companyName: c.companyName || "",
          email: c.email || "",
          phone: c.phone || c.mobile || "",
          gstin: c.gstin || "",
          state: c.state || "",
          paymentTerms: c.paymentTerms || "Due on Receipt",
          billingAddress: c.billingAddress,
          shippingAddress: c.shippingAddress,
        }));
        setCustomers(mappedCusts);

        const mappedItems: ItemOption[] = (itemsData.items || []).map((i: any) => ({
          id: i.id || i.sku,
          name: i.name,
          sku: i.sku,
          salesPrice: Number(i.salesPrice || 0),
          salesDescription: i.salesDescription || "",
          hsnCode: i.hsnCode || "",
          unit: i.unit || "pcs",
          gstRate: Number(i.gstRate ?? 18),
        }));
        setAvailableItems(mappedItems);

        // Pre-fill next invoice number if creating new invoice
        if (settingsData.settings) {
          const s = settingsData.settings as InvoiceSettingsData;
          setInvoiceSettings(s);
          const isAuto = s.autoGenerateNumbering !== false;
          setAutoGenerateNumbering(isAuto);

          if (!isEditing && !invoiceNumber && isAuto) {
            const formatted =
              s.formattedNextNumber ||
              formatInvoiceNumber(
                s.invoicePrefix || "INV-",
                s.nextNumber || 1,
                s.numberZeroPadding || 6,
              );
            setInvoiceNumber(formatted);
          }
        }
      })
      .catch((err) => {
        console.error("Master data load error:", err);
      })
      .finally(() => {
        if (isMounted) setIsLoadingMasterData(false);
      });

    return () => {
      isMounted = false;
    };
  }, [isEditing]);

  // Selected customer object
  const selectedCustomer = useMemo(() => {
    return customers.find((c) => c.id === selectedCustomerId);
  }, [customers, selectedCustomerId]);

  const handleNumberingSaved = (updated: InvoiceSettingsData) => {
    setInvoiceSettings(updated);
    const isAuto = updated.autoGenerateNumbering !== false;
    setAutoGenerateNumbering(isAuto);

    if (!isEditing && isAuto) {
      const formatted =
        updated.formattedNextNumber ||
        formatInvoiceNumber(
          updated.invoicePrefix || "INV-",
          updated.nextNumber || 1,
          updated.numberZeroPadding || 6,
        );
      setInvoiceNumber(formatted);
    }
  };

  const [customTerms, setCustomTerms] = useState<PaymentTermItem[]>([]);

  useEffect(() => {
    let active = true;
    fetch("/api/payment-terms")
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => {
        if (!active || !data?.terms) return;
        setCustomTerms(data.terms);
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, []);

  const allPaymentTermsOptions = useMemo(() => {
    const list = [...PAYMENT_TERMS_OPTIONS];
    for (const ct of customTerms) {
      if (ct.name && !list.includes(ct.name as any)) {
        list.push(ct.name as any);
      }
    }
    if (paymentTerms && !list.includes(paymentTerms as any)) {
      list.push(paymentTerms as any);
    }
    return list;
  }, [customTerms, paymentTerms]);

  // Auto-update due date when invoice date or terms change
  const updateDueDateFromTerms = (dateStr: string, terms: string) => {
    try {
      const calculated = calculateDueDateFromPaymentTerms(dateStr, terms, customTerms);
      setDueDate(calculated);
    } catch {
      setDueDate(dateStr);
    }
  };

  // Handle Customer Selection
  const handleCustomerChange = (customerId: string) => {
    setSelectedCustomerId(customerId);
    const matched = customers.find((c) => c.id === customerId);
    if (matched) {
      if (matched.state) {
        setPlaceOfSupply(matched.state);
      }
      if (matched.paymentTerms) {
        setPaymentTerms(matched.paymentTerms);
        // Auto-update due date
        updateDueDateFromTerms(invoiceDate, matched.paymentTerms);
      }
    }
  };

  useEffect(() => {
    if (!isEditing && customers.length > 0) {
      const urlCustomerId =
        typeof window !== "undefined"
          ? new URLSearchParams(window.location.search).get("customerId")
          : null;
      if (urlCustomerId) {
        const timer = setTimeout(() => {
          handleCustomerChange(urlCustomerId);
        }, 0);
        return () => clearTimeout(timer);
      }
    }
  }, [customers, isEditing]);

  // Row Manipulation
  const handleAddRow = () => {
    const newId = `row-${Date.now()}`;
    setRows((prev) => [
      ...prev,
      {
        rowId: newId,
        name: "",
        description: "",
        hsnCode: "",
        unit: "pcs",
        quantity: 1,
        rate: 0,
        discount: 0,
        discountType: "percent",
        taxRate: 18,
      },
    ]);
  };

  const handleRemoveRow = (rowId: string) => {
    if (rows.length === 1) {
      // Clear row instead of deleting last row
      setRows([
        {
          rowId: "row-1",
          name: "",
          description: "",
          hsnCode: "",
          unit: "pcs",
          quantity: 1,
          rate: 0,
          discount: 0,
          discountType: "percent",
          taxRate: 18,
        },
      ]);
      return;
    }
    setRows((prev) => prev.filter((r) => r.rowId !== rowId));
  };

  const handleUpdateRow = (rowId: string, updates: Partial<FormItemRow>) => {
    setRows((prev) =>
      prev.map((r) => (r.rowId === rowId ? { ...r, ...updates } : r)),
    );
  };

  const handleSelectItem = (rowId: string, itemId: string) => {
    const item = availableItems.find((i) => i.id === itemId);
    if (!item) return;

    handleUpdateRow(rowId, {
      itemId: item.id,
      name: item.name,
      description: item.salesDescription || "",
      hsnCode: item.hsnCode || "",
      unit: item.unit || "pcs",
      rate: item.salesPrice || 0,
      taxRate: item.gstRate !== undefined ? item.gstRate : 18,
    });
  };

  // Live Calculations
  const calculated = useMemo(() => {
    const calcItems = rows.map((r) => ({
      quantity: r.quantity,
      rate: r.rate,
      discount: r.discount,
      discountType: r.discountType,
      taxRate: r.taxRate,
    }));

    return calculateInvoiceTotals({
      items: calcItems,
      invoiceDiscount: Number(invoiceDiscount) || 0,
      invoiceDiscountType,
      shippingCharges: Number(shippingCharges) || 0,
      adjustment: Number(adjustment) || 0,
      autoRoundOff: true,
      placeOfSupply,
      organizationState: "Maharashtra",
      amountPaid: initialData?.amountPaid || 0,
    });
  }, [
    rows,
    invoiceDiscount,
    invoiceDiscountType,
    shippingCharges,
    adjustment,
    placeOfSupply,
    initialData?.amountPaid,
  ]);

  // Form Submit
  async function handleSubmit(status: "Draft" | "Sent") {
    if (!selectedCustomerId) {
      setError("Please select a customer.");
      return;
    }

    const hasValidItem = rows.some((r) => r.name.trim() && r.quantity > 0);
    if (!hasValidItem) {
      setError("Please add at least one line item with a name and quantity.");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      const payload = {
        number: invoiceNumber.trim() || undefined,
        customerId: selectedCustomerId,
        issueDate: invoiceDate,
        dueDate,
        paymentTerms,
        placeOfSupply,
        salesperson: salesperson.trim() || undefined,
        subject: subject.trim() || undefined,
        referenceNumber: referenceNumber.trim() || undefined,
        customerNotes: customerNotes.trim() || undefined,
        termsAndConditions: termsAndConditions.trim() || undefined,
        status,
        discount: Number(invoiceDiscount) || 0,
        discountType: invoiceDiscountType,
        shippingCharges: Number(shippingCharges) || 0,
        adjustment: Number(adjustment) || 0,
        items: rows
          .filter((r) => r.name.trim())
          .map((r) => ({
            itemId: r.itemId || undefined,
            name: r.name.trim(),
            description: r.description.trim() || undefined,
            hsnCode: r.hsnCode.trim() || undefined,
            unit: r.unit || "pcs",
            quantity: Number(r.quantity) || 1,
            rate: Number(r.rate) || 0,
            discount: Number(r.discount) || 0,
            discountType: r.discountType,
            taxRate: Number(r.taxRate) || 0,
          })),
      };

      const url = isEditing
        ? `/api/sales/invoices/${initialData?.id}`
        : "/api/sales/invoices";
      const method = isEditing ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to save invoice.");
      }

      const invoiceId = isEditing ? initialData?.id : data.invoice?.id;
      router.push(`/sales/invoices/${invoiceId}`);
    } catch (err: any) {
      setError(err.message || "Failed to save invoice.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div className="mx-auto max-w-5xl space-y-6 pb-12 text-slate-800">
      {/* 1. Header Bar */}
      <div className="flex items-center justify-between border-b border-slate-200 pb-4">
        <div className="flex items-center gap-3">
          <Link
            href="/sales/invoices"
            className="rounded-xl border border-slate-200 bg-white p-2 text-slate-500 shadow-xs hover:bg-slate-50 hover:text-slate-800 transition cursor-pointer"
          >
            <ArrowLeft className="h-4 w-4" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-slate-900">
              {isEditing ? `Edit Invoice ${invoiceNumber}` : "New Invoice"}
            </h1>
            <p className="text-xs text-slate-500">
              Create a compliant commercial tax invoice with live calculations
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2.5">
          <Link
            href="/sales/invoices"
            className="rounded-xl border border-slate-200 px-4 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-50 transition cursor-pointer"
          >
            Cancel
          </Link>
          <button
            type="button"
            onClick={() => handleSubmit("Draft")}
            disabled={isSubmitting}
            className="rounded-xl border border-slate-300 bg-white px-4 py-2 text-xs font-semibold text-slate-800 shadow-xs hover:bg-slate-50 disabled:opacity-50 transition cursor-pointer"
          >
            Save as Draft
          </button>
          <button
            type="button"
            onClick={() => handleSubmit("Sent")}
            disabled={isSubmitting}
            className="inline-flex items-center gap-1.5 rounded-xl bg-blue-600 px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-blue-700 disabled:opacity-50 transition cursor-pointer"
          >
            {isSubmitting ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Saving...
              </>
            ) : (
              "Save & Send"
            )}
          </button>
        </div>
      </div>

      {error && (
        <div className="rounded-xl bg-rose-50 border border-rose-200 p-4 text-xs font-medium text-rose-700 flex items-center justify-between shadow-xs">
          <span>{error}</span>
          <button
            type="button"
            onClick={() => setError(null)}
            className="text-rose-600 hover:text-rose-800 font-bold"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* 2. Primary Invoice Fields Card */}
      <div className="rounded-2xl border border-slate-200/90 bg-white p-6 shadow-xs space-y-6">
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {/* Customer Selection with Inline Quick Add Button */}
          <div className="sm:col-span-2">
            <div className="flex items-center justify-between mb-1.5">
              <label className="text-xs font-semibold text-slate-800">
                Customer Name <span className="text-rose-500">*</span>
              </label>
              <button
                type="button"
                onClick={() => setShowCustomerModal(true)}
                className="inline-flex items-center gap-1 text-xs font-bold text-blue-600 hover:text-blue-700 hover:underline cursor-pointer"
              >
                <Plus className="h-3.5 w-3.5" />
                New Customer
              </button>
            </div>
            <select
              value={selectedCustomerId}
              onChange={(e) => handleCustomerChange(e.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition"
            >
              <option value="">-- Select or search customer --</option>
              {customers.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name} {c.companyName ? `(${c.companyName})` : ""}
                </option>
              ))}
            </select>

            {/* Selected Customer Snapshot Pill */}
            {selectedCustomer && (
              <div className="mt-2.5 rounded-xl border border-blue-100 bg-blue-50/50 p-3 text-xs text-slate-700 flex flex-wrap items-center justify-between gap-2">
                <div>
                  <span className="font-bold text-slate-900">
                    {selectedCustomer.name}
                  </span>
                  {selectedCustomer.companyName && (
                    <span className="text-slate-500 ml-1">
                      • {selectedCustomer.companyName}
                    </span>
                  )}
                  {selectedCustomer.gstin && (
                    <span className="ml-2 font-mono font-medium text-slate-600">
                      GSTIN: {selectedCustomer.gstin}
                    </span>
                  )}
                </div>
                {selectedCustomer.state && (
                  <span className="rounded-md bg-white px-2 py-0.5 font-medium border border-blue-200 text-blue-700">
                    State: {selectedCustomer.state}
                  </span>
                )}
              </div>
            )}
          </div>

          {/* Invoice Number with Settings Gear */}
          <div>
            <label className="block text-xs font-semibold text-[#b91c1c] mb-1.5">
              Invoice#<span className="text-[#b91c1c]">*</span>
            </label>
            <div className="relative">
              <input
                type="text"
                required
                placeholder={autoGenerateNumbering ? "e.g. INV-000001" : "Enter invoice number"}
                value={invoiceNumber}
                onChange={(e) => setInvoiceNumber(e.target.value)}
                className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 pr-10 font-mono text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition"
              />
              <button
                type="button"
                id="invoice-number-config-btn"
                onClick={() => setShowNumberConfigModal(true)}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 rounded-lg p-1.5 text-blue-600 hover:text-blue-700 hover:bg-blue-50 transition cursor-pointer"
                title="Configure Invoice Number Preferences"
              >
                <Settings className="h-4 w-4" />
              </button>
            </div>
            {autoGenerateNumbering && (
              <p className="mt-1 text-[11px] text-slate-400">
                Auto-generated sequence. Click gear to customize prefix or sequence.
              </p>
            )}
          </div>

          {/* Invoice Date */}
          <div>
            <label className="block text-xs font-semibold text-slate-800 mb-1.5">
              Invoice Date
            </label>
            <input
              type="date"
              required
              value={invoiceDate}
              onChange={(e) => {
                setInvoiceDate(e.target.value);
                updateDueDateFromTerms(e.target.value, paymentTerms);
              }}
              className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
            />
          </div>

          {/* Payment Terms */}
          <div>
            <label className="block text-xs font-semibold text-slate-800 mb-1.5">
              Payment Terms
            </label>
            <select
              value={paymentTerms}
              onChange={(e) => {
                setPaymentTerms(e.target.value);
                updateDueDateFromTerms(invoiceDate, e.target.value);
              }}
              className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
            >
              {allPaymentTermsOptions.map((term) => (
                <option key={term} value={term}>
                  {term}
                </option>
              ))}
            </select>
          </div>

          {/* Due Date */}
          <div>
            <label className="block text-xs font-semibold text-slate-800 mb-1.5">
              Due Date
            </label>
            <input
              type="date"
              required
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
            />
          </div>

          {/* Place of Supply */}
          <div>
            <label className="block text-xs font-semibold text-slate-800 mb-1.5">
              Place of Supply (State)
            </label>
            <select
              value={placeOfSupply}
              onChange={(e) => setPlaceOfSupply(e.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
            >
              {INDIAN_STATES.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
          </div>

          {/* Reference # / PO # */}
          <div>
            <label className="block text-xs font-semibold text-slate-800 mb-1.5">
              Order / Reference #
            </label>
            <input
              type="text"
              placeholder="e.g. PO-8491, Client Ref"
              value={referenceNumber}
              onChange={(e) => setReferenceNumber(e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
            />
          </div>

          {/* Salesperson */}
          <div>
            <label className="block text-xs font-semibold text-slate-800 mb-1.5">
              Salesperson
            </label>
            <input
              type="text"
              placeholder="e.g. Anita Sharma"
              value={salesperson}
              onChange={(e) => setSalesperson(e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
            />
          </div>
        </div>

        {/* Subject line */}
        <div>
          <label className="block text-xs font-semibold text-slate-800 mb-1.5">
            Subject / Project
          </label>
          <input
            type="text"
            placeholder="e.g. Supply of Agro Commodities for Q4 Contract"
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            className="w-full rounded-xl border border-slate-200 px-3.5 py-2 text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10"
          />
        </div>
      </div>

      {/* 3. Line Items Grid Card */}
      <div className="rounded-2xl border border-slate-200/90 bg-white p-6 shadow-xs space-y-4">
        <div className="flex items-center justify-between pb-2 border-b border-slate-100">
          <div>
            <h3 className="text-base font-bold text-slate-900">Line Items</h3>
            <p className="text-xs text-slate-500">
              Add products, services, commodities, or custom line items
            </p>
          </div>
          <button
            type="button"
            onClick={() => {
              setActiveItemRowId(null);
              setShowItemModal(true);
            }}
            className="inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-white px-3 py-1.5 text-xs font-semibold text-blue-600 hover:bg-blue-50 transition cursor-pointer"
          >
            <Package className="h-3.5 w-3.5" />
            + New Product
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-slate-200 bg-slate-50/70 text-slate-600 font-semibold uppercase text-[11px]">
                <th className="py-2.5 px-3 min-w-[240px]">Item & Description</th>
                <th className="py-2.5 px-3 w-28">HSN/SAC</th>
                <th className="py-2.5 px-3 w-24">Qty</th>
                <th className="py-2.5 px-3 w-20">Unit</th>
                <th className="py-2.5 px-3 w-28 text-right">Rate (₹)</th>
                <th className="py-2.5 px-3 w-28 text-right">Disc (%)</th>
                <th className="py-2.5 px-3 w-32 text-right">Tax</th>
                <th className="py-2.5 px-3 w-32 text-right">Amount (₹)</th>
                <th className="py-2.5 px-2 w-10 text-center"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {rows.map((row, idx) => {
                const rowCalc = calculated.items[idx];
                return (
                  <tr key={row.rowId} className="hover:bg-slate-50/40 transition">
                    {/* Item Name / Picker */}
                    <td className="py-3 px-3 align-top">
                      <div className="space-y-1.5">
                        <div className="flex items-center gap-1.5">
                          <input
                            type="text"
                            required
                            placeholder="Type item name..."
                            value={row.name}
                            onChange={(e) =>
                              handleUpdateRow(row.rowId, { name: e.target.value })
                            }
                            className="w-full rounded-lg border border-slate-200 px-2.5 py-1.5 text-xs font-semibold text-slate-900 outline-none focus:border-blue-500"
                          />
                          {availableItems.length > 0 && (
                            <select
                              value={row.itemId || ""}
                              onChange={(e) =>
                                handleSelectItem(row.rowId, e.target.value)
                              }
                              title="Pick from items"
                              aria-label="Pick from items"
                              className="w-20 rounded-lg border border-slate-200 bg-slate-50 px-1 py-1.5 text-[11px] text-slate-600 outline-none"
                            >
                              <option value="">Select</option>
                              {availableItems.map((item) => (
                                <option key={item.id} value={item.id}>
                                  {item.name}
                                </option>
                              ))}
                            </select>
                          )}
                        </div>
                        <input
                          type="text"
                          placeholder="Description (optional)"
                          value={row.description}
                          onChange={(e) =>
                            handleUpdateRow(row.rowId, {
                              description: e.target.value,
                            })
                          }
                          className="w-full rounded-lg border border-slate-200/80 px-2.5 py-1 text-[11px] text-slate-600 outline-none focus:border-blue-500"
                        />
                      </div>
                    </td>

                    {/* HSN */}
                    <td className="py-3 px-3 align-top">
                      <input
                        type="text"
                        placeholder="HSN"
                        value={row.hsnCode}
                        onChange={(e) =>
                          handleUpdateRow(row.rowId, { hsnCode: e.target.value })
                        }
                        className="w-full rounded-lg border border-slate-200 px-2 py-1.5 font-mono text-xs text-slate-800 outline-none focus:border-blue-500"
                      />
                    </td>

                    {/* Qty */}
                    <td className="py-3 px-3 align-top">
                      <input
                        type="number"
                        min="0"
                        step="0.01"
                        required
                        value={row.quantity}
                        onChange={(e) =>
                          handleUpdateRow(row.rowId, {
                            quantity: Number(e.target.value),
                          })
                        }
                        className="w-full rounded-lg border border-slate-200 px-2 py-1.5 text-xs font-semibold text-slate-900 outline-none focus:border-blue-500"
                      />
