    countOverdue: 0,
    statusCounts: {
      total: 0,
      draft: 0,
      pending: 0,
      partiallyPaid: 0,
      paid: 0,
      overdue: 0,
      void: 0,
    },
  });

  const [loading, setLoading] = useState(true);
