  const [submittingPayment, setSubmittingPayment] = useState(false);

  // Delete modal state
  const [billToDelete, setBillToDelete] = useState<BillSummary | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchBills = async () => {
