"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Info, Layers, Loader2, Plus, X } from "lucide-react";
import { getFiscalYear, parseNextNumberInput } from "@/lib/purchase-order-numbering";

export interface PurchaseOrderPreferencesData {
  autoGenerateNumbering: boolean;
  prefix: string;
  nextNumber: number;
  numberZeroPadding: number;
  restartNumberingEachFiscalYear: boolean;
  lastFiscalYear?: string;
  formattedNextNumber?: string;
}

interface ConfigurePoNumberModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentSettings?: PurchaseOrderPreferencesData | null;
  onSaved: (updatedSettings: PurchaseOrderPreferencesData) => void;
}

export function ConfigurePoNumberModal({
  isOpen,
  onClose,
  currentSettings,
  onSaved,
}: ConfigurePoNumberModalProps) {
  const [mode, setMode] = useState<"auto" | "manual">("auto");
  const [prefix, setPrefix] = useState("PO-");
  const [nextNumberStr, setNextNumberStr] = useState("00002");
  const [restartFiscalYear, setRestartFiscalYear] = useState(false);
  const [showPrefixTags, setShowPrefixTags] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Sync state whenever modal opens or currentSettings changes
  useEffect(() => {
    if (isOpen) {
      const isAuto = currentSettings?.autoGenerateNumbering !== false;
      setMode(isAuto ? "auto" : "manual");
      setPrefix(currentSettings?.prefix || "PO-");

      const num = currentSettings?.nextNumber ?? 2;
      const pad = currentSettings?.numberZeroPadding ?? 5;
      setNextNumberStr(String(num).padStart(pad, "0"));

      setRestartFiscalYear(Boolean(currentSettings?.restartNumberingEachFiscalYear));
      setError(null);
      setShowPrefixTags(false);
    }
  }, [isOpen, currentSettings]);

  if (!isOpen) return null;

  const handleSave = async () => {
    setError(null);
    setSaving(true);

    try {
      const isAuto = mode === "auto";
      const cleanPrefix = isAuto ? prefix.trim() || "PO-" : prefix.trim();
      const parsedNum = parseNextNumberInput(nextNumberStr);

      const payload = {
        autoGenerateNumbering: isAuto,
        prefix: cleanPrefix,
        nextNumber: parsedNum.nextNumber,
        numberZeroPadding: parsedNum.padding,
        restartNumberingEachFiscalYear: isAuto ? restartFiscalYear : false,
      };

      const res = await fetch("/api/purchases/purchase-orders/preferences", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to save purchase order preferences.");
      }

      const updated: PurchaseOrderPreferencesData = {
        ...data.preferences,
        formattedNextNumber: data.formattedNextNumber,
      };
      onSaved(updated);
      onClose();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save preferences.";
      setError(msg);
    } finally {
      setSaving(false);
    }
  };

  const handleInsertTag = (tag: string) => {
    setPrefix((prev) => `${prev.trim()}${tag}`);
    setShowPrefixTags(false);
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-xs animate-in fade-in duration-150"
      role="dialog"
      aria-modal="true"
      aria-labelledby="configure-po-title"
    >
      <div className="relative w-full max-w-xl rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between pb-3">
          <h3
            id="configure-po-title"
            className="text-base sm:text-lg font-bold text-slate-900"
          >
            Configure Purchase Order# Preferences
          </h3>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1 text-rose-500 hover:bg-rose-50 hover:text-rose-600 transition cursor-pointer"
            title="Close"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Top Banner Card: Transaction Number Series */}
        <div className="mt-2 rounded-xl border border-slate-200/90 bg-slate-50/70 p-3.5 flex items-start gap-3">
          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-700 text-white mt-0.5">
            <Layers className="h-4 w-4" />
          </div>
          <div className="flex-1 text-xs text-slate-600 leading-relaxed">
            Configure multiple transaction number series to auto-generate transaction numbers with unique prefixes according to your business needs.
          </div>
          <Link
            href="/settings/preferences"
            onClick={onClose}
            className="text-xs font-semibold text-blue-600 hover:text-blue-700 hover:underline shrink-0 flex items-center gap-0.5 mt-0.5"
          >
            Configure →
          </Link>
        </div>

        {/* Divider */}
        <div className="my-4 border-t border-slate-100" />

        {/* Error notice if any */}
        {error && (
          <div className="mb-4 rounded-xl border border-rose-200 bg-rose-50 p-3 text-xs text-rose-700">
            {error}
          </div>
        )}

        {/* Informational Text */}
        <p className="text-xs sm:text-sm text-slate-700 leading-normal">
          Your purchase order numbers are set on auto-generate mode to save your time.
          <br />
          Are you sure about changing this setting?
        </p>

        {/* Options */}
        <div className="mt-4 space-y-4">
          {/* Option 1: Continue auto-generating */}
          <div>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="radio"
                name="po-numbering-mode"
                checked={mode === "auto"}
                onChange={() => setMode("auto")}
                className="h-4 w-4 border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
              />
              <span className="text-xs sm:text-sm font-semibold text-slate-900">
                Continue auto-generating purchase order numbers
              </span>
              <span
                className="text-slate-400 hover:text-slate-600 cursor-help"
                title="Purchase order numbers will be generated automatically in sequence for each new purchase order."
              >
                <Info className="h-3.5 w-3.5" />
              </span>
            </label>

            {/* Prefix & Next Number inputs (Indented) */}
            <div
              className={`ml-6 mt-3 space-y-3 transition-opacity ${
                mode === "auto" ? "opacity-100" : "opacity-40 pointer-events-none"
              }`}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Prefix */}
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Prefix
                  </label>
                  <div className="relative">
                    <input
                      type="text"
                      disabled={mode !== "auto"}
                      value={prefix}
                      onChange={(e) => setPrefix(e.target.value)}
                      placeholder="PO-"
                      className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 pr-9 font-mono text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition"
                    />
                    <div className="absolute right-2.5 top-1/2 -translate-y-1/2">
                      <button
                        type="button"
                        onClick={() => setShowPrefixTags(!showPrefixTags)}
                        className="flex h-5 w-5 items-center justify-center rounded-full bg-blue-50 text-blue-600 hover:bg-blue-100 transition cursor-pointer"
                        title="Add prefix variable tag"
                      >
                        <Plus className="h-3.5 w-3.5" />
                      </button>

                      {showPrefixTags && (
                        <div className="absolute right-0 top-full mt-1.5 w-48 rounded-xl border border-slate-200 bg-white p-1.5 shadow-xl z-50 text-xs animate-in fade-in duration-100">
                          <div className="px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-400">
                            Insert variable tag
                          </div>
                          <button
                            type="button"
                            onClick={() => handleInsertTag(`${new Date().getFullYear()}/`)}
                            className="w-full rounded-lg px-2 py-1.5 text-left text-slate-700 hover:bg-blue-50 hover:text-blue-700 cursor-pointer"
                          >
                            {new Date().getFullYear()}/ (Year)
                          </button>
                          <button
                            type="button"
                            onClick={() => handleInsertTag(`${getFiscalYear()}/`)}
                            className="w-full rounded-lg px-2 py-1.5 text-left text-slate-700 hover:bg-blue-50 hover:text-blue-700 cursor-pointer"
                          >
                            {getFiscalYear()}/ (Financial Year)
                          </button>
                          <button
                            type="button"
                            onClick={() =>
                              handleInsertTag(
                                `${String(new Date().getMonth() + 1).padStart(2, "0")}/`,
                              )
                            }
                            className="w-full rounded-lg px-2 py-1.5 text-left text-slate-700 hover:bg-blue-50 hover:text-blue-700 cursor-pointer"
                          >
                            MM/ (Month Number)
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {/* Next Number */}
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Next Number
                  </label>
                  <input
                    type="text"
                    disabled={mode !== "auto"}
                    value={nextNumberStr}
                    onChange={(e) => {
                      const val = e.target.value.replace(/[^0-9]/g, "");
                      setNextNumberStr(val);
                    }}
                    placeholder="00002"
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 font-mono text-sm text-slate-900 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition"
                  />
                </div>
              </div>

              {/* Fiscal Year Restart Checkbox */}
              <label className="flex items-center gap-2 cursor-pointer pt-0.5">
                <input
                  type="checkbox"
                  disabled={mode !== "auto"}
                  checked={restartFiscalYear}
                  onChange={(e) => setRestartFiscalYear(e.target.checked)}
                  className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                />
                <span className="text-xs text-slate-700">
                  Restart numbering for purchase orders at the start of each fiscal year.
                </span>
              </label>
            </div>
          </div>

          {/* Option 2: Enter manually */}
          <div className="pt-1">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="radio"
                name="po-numbering-mode"
                checked={mode === "manual"}
                onChange={() => setMode("manual")}
                className="h-4 w-4 border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
              />
              <span className="text-xs sm:text-sm font-semibold text-slate-900">
                Enter purchase order numbers manually
              </span>
            </label>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="mt-6 pt-4 border-t border-slate-100 flex items-center justify-start gap-3">
          <button
            type="button"
            onClick={handleSave}
            disabled={saving}
            className="inline-flex items-center gap-1.5 rounded-lg bg-blue-600 px-5 py-2 text-sm font-medium text-white shadow-xs hover:bg-blue-700 transition cursor-pointer disabled:opacity-50"
          >
            {saving && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            Save
          </button>
          <button
            type="button"
            onClick={onClose}
            disabled={saving}
            className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50 transition cursor-pointer"
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}

