        setAmount(p.amount ? String(p.amount) : "");
        setCurrency(p.currency || "INR");
        setPaidThrough(p.paidThrough || "HDFC Primary Bank");
        setVendor(p.vendor || "");
        setNotes(p.notes || "");
        setCustomerName(p.customerName || "");
