          >
            {isSubmitting ? (
              <>
                <RotateCw className="h-4 w-4 animate-spin" />
                Saving…
              </>
            ) : (
              <>
                <CheckCircle2 className="h-4 w-4" />
                Save Recurring Expense
              </>
            )}
          </button>
        </div>
      </form>

      {/* Vendor Search Modal */}
      {vendorModalOpen && (
        <div
