                            <option key={it.id} value={it.id}>
                              {it.name} (₹{it.rate || 0})
                            </option>
                          ))}
                        </select>
                      )}
                    </div>
                    <input
                      type="text"
                      value={row.description}
                      onChange={(e) => handleItemChange(row.id, "description", e.target.value)}
