      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Total Credit Value */}
        <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
