  const handleCreateNew = () => {
    setEditingReport(null);
    setActiveTab("builder");
  };

  const handleSavedSuccess = () => {
    setSavedRefreshTrigger((prev) => prev + 1);
    setActiveTab("saved");
    setEditingReport(null);
