                  <span className="mt-1 text-[11px] text-slate-500">{item.desc}</span>
                  <div className="mt-3 flex items-center gap-1 text-[11px] font-semibold text-blue-600">
                    <span>Create</span>
                    <ChevronRight className="h-3 w-3" />
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

