"use client";

import { useEffect, useState } from "react";
import { Info, Layers, Loader2, X } from "lucide-react";
import { getFiscalYear, parseNextNumberInput } from "@/lib/delivery-challan-numbering";
import { type DeliveryChallanPreferencesData } from "./delivery-challan-types";

interface ConfigureDcNumberModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentSettings?: DeliveryChallanPreferencesData | null;
  onSaved: (updatedSettings: DeliveryChallanPreferencesData) => void;
}

export function ConfigureDcNumberModal({
  isOpen,
  onClose,
  currentSettings,
  onSaved,
}: ConfigureDcNumberModalProps) {
  const [mode, setMode] = useState<"auto" | "manual">("auto");
  const [prefix, setPrefix] = useState("DC-");
  const [nextNumberStr, setNextNumberStr] = useState("00002");
  const [restartFiscalYear, setRestartFiscalYear] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      const isAuto = currentSettings?.autoGenerateNumbering !== false;
      setMode(isAuto ? "auto" : "manual");
      setPrefix(currentSettings?.prefix || "DC-");

      const num = currentSettings?.nextNumber ?? 2;
      const pad = currentSettings?.numberZeroPadding ?? 5;
      setNextNumberStr(String(num).padStart(pad, "0"));

      setRestartFiscalYear(Boolean(currentSettings?.restartNumberingEachFiscalYear));
      setError(null);
    }
  }, [isOpen, currentSettings]);

  if (!isOpen) return null;

  const handleSave = async () => {
    setError(null);
    setSaving(true);

    try {
      const isAuto = mode === "auto";
      const cleanPrefix = isAuto ? prefix.trim() || "DC-" : prefix.trim();
      const parsedNum = parseNextNumberInput(nextNumberStr);

      const payload = {
        autoGenerateNumbering: isAuto,
        prefix: cleanPrefix,
        nextNumber: parsedNum.nextNumber,
        numberZeroPadding: parsedNum.padding,
        restartNumberingEachFiscalYear: isAuto ? restartFiscalYear : false,
      };

      const res = await fetch("/api/sales/delivery-challans/preferences", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to save delivery challan numbering settings.");
      }

      onSaved(data.settings);
      onClose();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Failed to save settings.");
    } finally {
      setSaving(false);
    }
  };

  const previewFormatted = `${prefix.trim() || "DC-"}${nextNumberStr.trim() || "00001"}`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-xs animate-in fade-in">
      <div className="bg-white rounded-2xl max-w-lg w-full p-6 shadow-2xl border border-slate-200">
        <div className="flex items-center justify-between pb-4 border-b border-slate-100">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center font-bold text-xs">
              <Layers className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900 tracking-tight">
                Configure Delivery Challan Number
              </h3>
              <p className="text-xs text-slate-500">
                Set up automated serial prefix & auto-incrementing numbers
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 p-1.5 rounded-lg hover:bg-slate-100 transition"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && (
          <div className="mt-4 p-3 rounded-xl bg-rose-50 border border-rose-200 text-rose-700 text-xs flex items-center gap-2">
            <Info className="w-4 h-4 shrink-0 text-rose-500" />
            <span>{error}</span>
          </div>
        )}

        <div className="py-4 space-y-4">
          <div className="space-y-2">
            <label className="text-xs font-semibold text-slate-700">Numbering Mode</label>
            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setMode("auto")}
                className={`px-3 py-2.5 text-xs font-semibold rounded-xl border text-left transition ${
                  mode === "auto"
                    ? "border-blue-600 bg-blue-50/60 text-blue-700 shadow-xs"
                    : "border-slate-200 text-slate-600 hover:bg-slate-50"
                }`}
              >
                Auto-generate
                <p className="text-[11px] font-normal text-slate-500 mt-0.5">
                  Increment sequentially
                </p>
              </button>
              <button
                type="button"
                onClick={() => setMode("manual")}
                className={`px-3 py-2.5 text-xs font-semibold rounded-xl border text-left transition ${
                  mode === "manual"
                    ? "border-blue-600 bg-blue-50/60 text-blue-700 shadow-xs"
                    : "border-slate-200 text-slate-600 hover:bg-slate-50"
                }`}
              >
                Manual Entry
                <p className="text-[11px] font-normal text-slate-500 mt-0.5">
                  Type custom number each time
                </p>
              </button>
            </div>
          </div>

          {mode === "auto" && (
            <div className="space-y-3 pt-1">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Prefix
                  </label>
                  <input
                    type="text"
                    value={prefix}
                    onChange={(e) => setPrefix(e.target.value)}
                    placeholder="DC-"
                    className="w-full px-3 py-2 text-xs border border-slate-200 rounded-xl outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition font-mono"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Next Number
                  </label>
                  <input
                    type="text"
                    value={nextNumberStr}
                    onChange={(e) => setNextNumberStr(e.target.value)}
                    placeholder="00002"
                    className="w-full px-3 py-2 text-xs border border-slate-200 rounded-xl outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition font-mono"
                  />
                </div>
              </div>

              <div className="p-3 bg-slate-50 border border-slate-200/80 rounded-xl text-xs">
                <span className="text-slate-500">Live Preview: </span>
                <span className="font-mono font-bold text-slate-900 bg-white px-2 py-0.5 rounded border border-slate-200 ml-1">
                  {previewFormatted}
                </span>
              </div>

              <label className="flex items-start gap-2.5 pt-1 cursor-pointer">
                <input
                  type="checkbox"
                  checked={restartFiscalYear}
                  onChange={(e) => setRestartFiscalYear(e.target.checked)}
                  className="w-4 h-4 text-blue-600 rounded mt-0.5"
                />
                <span className="text-xs text-slate-600 leading-snug">
                  Restart numbering each financial year (e.g., FY {getFiscalYear()})
                </span>
              </label>
            </div>
          )}
        </div>

        <div className="flex justify-end gap-2.5 pt-4 border-t border-slate-100">
          <button
            type="button"
            onClick={onClose}
            disabled={saving}
            className="px-4 py-2 text-xs font-semibold text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-xl transition"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleSave}
            disabled={saving}
            className="px-4 py-2 text-xs font-semibold bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow-xs transition flex items-center gap-1.5"
          >
            {saving && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
            Save Settings
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import {
  Calendar,
  CheckCircle,
  Download,
  Edit2,
  FileText,
  Printer,
  Trash2,
  X,
} from "lucide-react";
import { type DeliveryChallanDocument } from "./delivery-challan-types";
import {
  downloadDeliveryChallanPDF,
  printDeliveryChallan,
} from "./delivery-challan-pdf-generator";

interface DeliveryChallanDetailModalProps {
  challan: DeliveryChallanDocument | null;
  isOpen: boolean;
  onClose: () => void;
  onDelete: (id: string, number: string) => Promise<void>;
  onStatusChange: (id: string, newStatus: string) => Promise<void>;
}

export function DeliveryChallanDetailModal({
  challan,
  isOpen,
  onClose,
  onDelete,
  onStatusChange,
}: DeliveryChallanDetailModalProps) {
  const [downloading, setDownloading] = useState(false);
  const [printing, setPrinting] = useState(false);

  if (!isOpen || !challan) return null;

  const handleDownloadPDF = async () => {
    try {
      setDownloading(true);
      await downloadDeliveryChallanPDF(challan, challan.customerSnapshot);
    } catch (err) {
      alert("Failed to download PDF.");
    } finally {
      setDownloading(false);
    }
  };

  const handlePrint = async () => {
    try {
      setPrinting(true);
      await printDeliveryChallan(challan, challan.customerSnapshot);
    } catch (err) {
      alert("Failed to print delivery challan.");
    } finally {
      setPrinting(false);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "Delivered":
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
            Delivered
          </span>
        );
      case "Open":
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-blue-50 text-blue-700 border border-blue-200">
            Open
          </span>
        );
      case "Draft":
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-amber-50 text-amber-700 border border-amber-200">
            Draft
          </span>
        );
      case "Closed":
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-purple-50 text-purple-700 border border-purple-200">
            Closed
          </span>
        );
      default:
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-slate-100 text-slate-600 border border-slate-200">
            {status}
          </span>
        );
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-xs animate-in fade-in">
      <div className="bg-white rounded-2xl max-w-3xl w-full max-h-[90vh] flex flex-col shadow-2xl border border-slate-200">
        {/* Modal Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-bold">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-slate-900 tracking-tight">
                  {challan.deliveryChallanNumber}
                </h3>
                {getStatusBadge(challan.status)}
              </div>
              <p className="text-xs text-slate-500">
                Created on {new Date(challan.deliveryChallanDate).toLocaleDateString("en-IN")}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handlePrint}
              disabled={printing}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold border border-slate-200 rounded-xl hover:bg-slate-50 transition text-slate-700 cursor-pointer"
            >
              <Printer className="w-3.5 h-3.5" />
              {printing ? "Preparing…" : "Print"}
            </button>
            <button
              type="button"
              onClick={handleDownloadPDF}
              disabled={downloading}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold border border-slate-200 rounded-xl hover:bg-slate-50 transition text-slate-700 cursor-pointer"
            >
              <Download className="w-3.5 h-3.5" />
              {downloading ? "Downloading…" : "Download PDF"}
            </button>
            <Link
              href={`/sales/delivery-challans/${challan.id}/edit`}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow-xs transition"
            >
              <Edit2 className="w-3.5 h-3.5" />
              Edit
            </Link>
            <button
              type="button"
              onClick={onClose}
              className="text-slate-400 hover:text-slate-600 p-1.5 rounded-xl hover:bg-slate-100 transition cursor-pointer ml-1"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Modal Scrollable Content */}
        <div className="p-6 overflow-y-auto space-y-6 text-xs">
          {/* Challan & Customer Overview */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 rounded-xl border border-slate-200 bg-slate-50/50 space-y-2">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                Deliver To
              </span>
              <p className="text-sm font-bold text-slate-900">{challan.customerName}</p>
              {challan.customerSnapshot?.email && (
                <p className="text-slate-500">{challan.customerSnapshot.email}</p>
              )}
              {challan.customerSnapshot?.phone && (
                <p className="text-slate-500">{challan.customerSnapshot.phone}</p>
              )}
              {challan.customerSnapshot?.gstin && (
                <p className="text-slate-500 font-mono">GSTIN: {challan.customerSnapshot.gstin}</p>
              )}
            </div>

            <div className="p-4 rounded-xl border border-slate-200 bg-slate-50/50 space-y-2">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                Challan Details
              </span>
              <div className="grid grid-cols-2 gap-2 text-slate-700">
                <span className="text-slate-500">Challan Type:</span>
                <span className="font-semibold text-blue-600">{challan.challanType}</span>

                <span className="text-slate-500">Challan Date:</span>
                <span className="font-medium">
                  {new Date(challan.deliveryChallanDate).toLocaleDateString("en-IN")}
                </span>

                {challan.referenceNumber && (
                  <>
                    <span className="text-slate-500">Reference#:</span>
                    <span className="font-mono">{challan.referenceNumber}</span>
                  </>
                )}

                <span className="text-slate-500">Status:</span>
                <div>{getStatusBadge(challan.status)}</div>
              </div>
            </div>
          </div>

          {/* Items Table */}
          <div className="border border-slate-200 rounded-xl overflow-hidden">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-[11px] font-semibold uppercase">
                  <th className="py-2 px-3 text-left">#</th>
                  <th className="py-2 px-3 text-left">Item Details</th>
                  <th className="py-2 px-3 text-right">Quantity</th>
                  <th className="py-2 px-3 text-right">Rate</th>
                  <th className="py-2 px-3 text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {challan.items.map((it, idx) => (
                  <tr key={idx} className="hover:bg-slate-50/50">
                    <td className="py-2.5 px-3 text-slate-400">{idx + 1}</td>
                    <td className="py-2.5 px-3">
                      <p className="font-semibold text-slate-900">{it.name}</p>
                      {it.description && (
                        <p className="text-slate-500 text-[11px]">{it.description}</p>
                      )}
                    </td>
                    <td className="py-2.5 px-3 text-right tabular-nums">
                      {it.quantity} {it.unit || "pcs"}
                    </td>
                    <td className="py-2.5 px-3 text-right tabular-nums">₹{it.rate.toFixed(2)}</td>
                    <td className="py-2.5 px-3 text-right font-bold text-slate-900 tabular-nums">
                      ₹{it.amount.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Calculations Breakdown */}
          <div className="flex justify-end">
            <div className="w-64 space-y-2 p-3 bg-slate-50 rounded-xl border border-slate-200">
              <div className="flex justify-between text-slate-600">
                <span>Sub Total:</span>
                <span className="tabular-nums font-medium">₹{challan.subTotal.toFixed(2)}</span>
              </div>
              {challan.discount > 0 && (
                <div className="flex justify-between text-slate-600">
                  <span>
                    Discount {challan.discountType === "percent" ? `(${challan.discount}%)` : ""}:
                  </span>
                  <span className="tabular-nums font-medium">
                    -₹
                    {(challan.discountType === "percent"
                      ? challan.subTotal * (challan.discount / 100)
                      : challan.discount
                    ).toFixed(2)}
                  </span>
                </div>
              )}
              {challan.adjustment !== 0 && (
                <div className="flex justify-between text-slate-600">
                  <span>Adjustment:</span>
                  <span className="tabular-nums font-medium">
                    {challan.adjustment >= 0 ? "+" : "-"}₹{Math.abs(challan.adjustment).toFixed(2)}
                  </span>
                </div>
              )}
              <div className="border-t border-slate-200 pt-2 flex justify-between font-bold text-slate-900">
                <span>Grand Total:</span>
                <span className="tabular-nums text-sm">₹{challan.total.toFixed(2)}</span>
              </div>
            </div>
          </div>

          {/* Notes and Terms */}
          {(challan.customerNotes || challan.termsAndConditions) && (
            <div className="space-y-3 pt-2">
              {challan.customerNotes && (
                <div>
                  <span className="font-bold text-slate-700">Customer Notes:</span>
                  <p className="text-slate-600 mt-0.5">{challan.customerNotes}</p>
                </div>
              )}
              {challan.termsAndConditions && (
                <div>
                  <span className="font-bold text-slate-700">Terms & Conditions:</span>
                  <p className="text-slate-600 mt-0.5 whitespace-pre-line">
                    {challan.termsAndConditions}
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Modal Footer with Status Change & Delete */}
        <div className="flex items-center justify-between px-6 py-3.5 border-t border-slate-100 bg-slate-50/50">
          <button
            type="button"
            onClick={() => onDelete(challan.id, challan.deliveryChallanNumber)}
            className="inline-flex items-center gap-1.5 text-xs font-semibold text-rose-600 hover:text-rose-700 cursor-pointer"
          >
            <Trash2 className="w-3.5 h-3.5" />
            Delete Challan
          </button>

          <div className="flex items-center gap-2">
            {challan.status !== "Delivered" && (
              <button
                type="button"
                onClick={() => onStatusChange(challan.id, "Delivered")}
                className="px-3 py-1.5 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl shadow-xs transition cursor-pointer"
              >
                Mark as Delivered
              </button>
            )}
            {challan.status === "Delivered" && (
              <button
                type="button"
                onClick={() => onStatusChange(challan.id, "Closed")}
                className="px-3 py-1.5 text-xs font-semibold bg-purple-600 hover:bg-purple-700 text-white rounded-xl shadow-xs transition cursor-pointer"
              >
                Mark as Closed
              </button>
            )}
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-1.5 text-xs font-semibold border border-slate-200 rounded-xl hover:bg-slate-100 transition cursor-pointer"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * components/sales/delivery-challan/delivery-challan-pdf-generator.ts
 *
 * Professional client-side A4 PDF generator and print utility for Delivery Challans using jsPDF.
 */

import { jsPDF } from "jspdf";
import { formatCurrency, numberToIndianWords } from "@/lib/invoice-utils";
import { type DeliveryChallanDocument, type CustomerOption } from "./delivery-challan-types";

export interface CompanyProfileInfo {
  logo?: string;
  companyName?: string;
  email?: string;
  phone?: string;
  address?: string;
  gstin?: string;
}

let cachedProfileInfo: CompanyProfileInfo | null = null;

export async function fetchCompanyProfile(): Promise<CompanyProfileInfo> {
  if (cachedProfileInfo) return cachedProfileInfo;
  if (typeof window === "undefined") return {};

  try {
    const res = await fetch("/api/profile");
    if (!res.ok) return {};
    const data = await res.json();
    const p = data?.profile;
    if (!p) return {};

    const profile: CompanyProfileInfo = {
      logo: p.logo || undefined,
      companyName: p.organizationName || p.tradeName || "Bharat Traders & Commodities Ltd.",
      email: p.email || "billing@ledgerflow.io",
      phone: p.phone || "+91 98765 43210",
      address: [p.address, p.city, p.state, p.pincode].filter(Boolean).join(", ") || "APMC Market Yard, Navi Mumbai, India",
      gstin: p.gstin || undefined,
    };
    cachedProfileInfo = profile;
    return profile;
  } catch {
    return {
      companyName: "Bharat Traders & Commodities Ltd.",
      email: "billing@ledgerflow.io",
      phone: "+91 98765 43210",
      address: "APMC Market Yard, Navi Mumbai, India",
    };
  }
}

function formatDate(dateStr?: string | Date): string {
  if (!dateStr) return "-";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return String(dateStr);
    const day = String(d.getDate()).padStart(2, "0");
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const year = d.getFullYear();
    return `${day}/${month}/${year}`;
  } catch {
    return String(dateStr);
  }
}

export async function generateDeliveryChallanPDF(
  challan: DeliveryChallanDocument,
  customer?: CustomerOption | null,
): Promise<jsPDF> {
  const profile = await fetchCompanyProfile();
  const doc = new jsPDF({
    orientation: "portrait",
    unit: "mm",
    format: "a4",
  });

  const pageWidth = 210;
  const pageHeight = 297;
  const margin = 14;
  const contentWidth = pageWidth - margin * 2;
  let y = margin;

  // Header band
  doc.setFillColor(248, 250, 252);
  doc.rect(margin, y, contentWidth, 34, "F");

  // Company Name
  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.setTextColor(30, 41, 59); // slate-800
  doc.text(profile.companyName || "Bharat Traders & Commodities Ltd.", margin + 4, y + 8);

  // Subtitle / Address
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(100, 116, 139); // slate-500
  doc.text(profile.address || "", margin + 4, y + 14);

  const contactText = [profile.email, profile.phone, profile.gstin ? `GSTIN: ${profile.gstin}` : ""].filter(Boolean).join(" · ");
  doc.text(contactText, margin + 4, y + 19);

  // Top right: DELIVERY CHALLAN header
  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.setTextColor(37, 99, 235); // blue-600
  doc.text("DELIVERY CHALLAN", pageWidth - margin - 4, y + 9, { align: "right" });

  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.setTextColor(30, 41, 59);
  doc.text(`Challan #: ${challan.deliveryChallanNumber}`, pageWidth - margin - 4, y + 16, { align: "right" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(100, 116, 139);
  doc.text(`Date: ${formatDate(challan.deliveryChallanDate)}`, pageWidth - margin - 4, y + 21, { align: "right" });

  if (challan.referenceNumber) {
    doc.text(`Ref #: ${challan.referenceNumber}`, pageWidth - margin - 4, y + 26, { align: "right" });
  }

  y += 40;

  // Challan Info Bar & Customer details
  const colWidth = (contentWidth - 6) / 2;

  // Left card: Deliver To / Customer
  doc.setDrawColor(226, 232, 240); // slate-200
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(margin, y, colWidth, 38, 2, 2, "FD");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text("DELIVER TO (CUSTOMER)", margin + 4, y + 6);

  const custName = challan.customerName || customer?.name || "Customer";
  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.setTextColor(15, 23, 42); // slate-900
  doc.text(custName, margin + 4, y + 12);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(71, 85, 105);

  const snap = challan.customerSnapshot || customer;
  const addressParts = [
    snap?.billingAddress?.street || snap?.shippingAddress?.street,
    snap?.billingAddress?.city || snap?.shippingAddress?.city,
    snap?.billingAddress?.state || snap?.shippingAddress?.state,
    snap?.billingAddress?.postalCode || snap?.shippingAddress?.postalCode,
  ].filter(Boolean);

  let custY = y + 17;
  if (addressParts.length > 0) {
    doc.text(addressParts.join(", "), margin + 4, custY);
    custY += 4.5;
  }
  if (snap?.email || snap?.phone) {
    doc.text([snap.email, snap.phone].filter(Boolean).join(" · "), margin + 4, custY);
    custY += 4.5;
  }
  if (snap?.gstin) {
    doc.text(`GSTIN: ${snap.gstin}`, margin + 4, custY);
  }

  // Right card: Challan Specifications
  doc.roundedRect(margin + colWidth + 6, y, colWidth, 38, 2, 2, "FD");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text("CHALLAN DETAILS", margin + colWidth + 10, y + 6);

  let specY = y + 12;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.setTextColor(15, 23, 42);
  doc.text("Challan Type:", margin + colWidth + 10, specY);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(37, 99, 235);
  doc.text(challan.challanType || "Supply on Approval", margin + colWidth + 40, specY);
  specY += 6;

  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text("Status:", margin + colWidth + 10, specY);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(challan.status === "Delivered" ? "#16a34a" : "#2563eb");
  doc.text(challan.status || "Draft", margin + colWidth + 40, specY);
  specY += 6;

  if (challan.referenceNumber) {
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text("Reference #:", margin + colWidth + 10, specY);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(71, 85, 105);
    doc.text(challan.referenceNumber, margin + colWidth + 40, specY);
  }

  y += 44;

  // Table header
  doc.setFillColor(37, 99, 235); // blue-600
  doc.rect(margin, y, contentWidth, 8, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8.5);
  doc.setTextColor(255, 255, 255);

  const colSno = margin + 3;
  const colItem = margin + 14;
  const colQty = margin + 115;
  const colRate = margin + 145;
  const colAmt = pageWidth - margin - 3;

  doc.text("#", colSno, y + 5.5);
  doc.text("ITEM DETAILS", colItem, y + 5.5);
  doc.text("QUANTITY", colQty, y + 5.5, { align: "right" });
  doc.text("RATE (₹)", colRate, y + 5.5, { align: "right" });
  doc.text("AMOUNT (₹)", colAmt, y + 5.5, { align: "right" });

  y += 8;

  // Table rows
  const items = challan.items || [];
  let rowIndex = 0;

  for (const item of items) {
    const isEven = rowIndex % 2 === 0;
    const rowHeight = item.description ? 12 : 8;

    if (y + rowHeight > pageHeight - 65) {
      doc.addPage();
      y = margin;
    }

    if (!isEven) {
      doc.setFillColor(248, 250, 252);
      doc.rect(margin, y, contentWidth, rowHeight, "F");
    }

    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    doc.setTextColor(71, 85, 105);
    doc.text(String(rowIndex + 1), colSno, y + 5);

    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 23, 42);
    doc.text(item.name || "Item", colItem, y + 5);

    if (item.description) {
      doc.setFont("helvetica", "normal");
      doc.setFontSize(7.5);
      doc.setTextColor(148, 163, 184);
      doc.text(item.description.slice(0, 70), colItem, y + 9.5);
    }

    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    doc.setTextColor(30, 41, 59);
    const qtyText = `${item.quantity || 1} ${item.unit || "pcs"}`;
    doc.text(qtyText, colQty, y + 5, { align: "right" });
    doc.text(Number(item.rate || 0).toFixed(2), colRate, y + 5, { align: "right" });

    doc.setFont("helvetica", "bold");
    doc.text(Number(item.amount || 0).toFixed(2), colAmt, y + 5, { align: "right" });

    doc.setDrawColor(241, 245, 249);
    doc.line(margin, y + rowHeight, pageWidth - margin, y + rowHeight);

    y += rowHeight;
    rowIndex++;
  }

  y += 6;

  // Summary section
  const summaryBoxWidth = 80;
  const summaryLeft = pageWidth - margin - summaryBoxWidth;

  // Left side: In Indian Currency Words
  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text("TOTAL IN WORDS", margin, y + 4);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(15, 23, 42);
  const words = numberToIndianWords(Math.round(challan.total || 0));
  doc.text(`Indian Rupees ${words} Only`, margin, y + 9, { maxWidth: contentWidth - summaryBoxWidth - 10 });

  // Right side: Calculations
  let calcY = y + 4;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(71, 85, 105);

  doc.text("Sub Total:", summaryLeft, calcY);
  doc.text(`₹ ${Number(challan.subTotal || 0).toFixed(2)}`, colAmt, calcY, { align: "right" });
  calcY += 5.5;

  if (challan.discount) {
    const discLabel = challan.discountType === "percent" ? `Discount (${challan.discount}%):` : "Discount:";
    doc.text(discLabel, summaryLeft, calcY);
    const discAmt = challan.discountType === "percent"
      ? (challan.subTotal * (challan.discount / 100))
      : challan.discount;
    doc.text(`- ₹ ${Number(discAmt).toFixed(2)}`, colAmt, calcY, { align: "right" });
    calcY += 5.5;
  }

  if (challan.adjustment) {
    doc.text("Adjustment:", summaryLeft, calcY);
    doc.text(`${challan.adjustment >= 0 ? "+" : "-"} ₹ ${Math.abs(challan.adjustment).toFixed(2)}`, colAmt, calcY, { align: "right" });
    calcY += 5.5;
  }

  doc.setDrawColor(226, 232, 240);
  doc.line(summaryLeft, calcY - 1, pageWidth - margin, calcY - 1);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.setTextColor(15, 23, 42);
  doc.text("Total ( ₹ ):", summaryLeft, calcY + 5);
  doc.text(`₹ ${Number(challan.total || 0).toFixed(2)}`, colAmt, calcY + 5, { align: "right" });

  y = Math.max(calcY + 16, y + 25);

  // Notes and Terms
  if (challan.customerNotes || challan.termsAndConditions) {
    if (challan.customerNotes) {
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8);
      doc.setTextColor(100, 116, 139);
      doc.text("CUSTOMER NOTES", margin, y);
      y += 4.5;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(71, 85, 105);
      doc.text(challan.customerNotes, margin, y, { maxWidth: contentWidth });
      y += 8;
    }

    if (challan.termsAndConditions) {
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8);
      doc.setTextColor(100, 116, 139);
      doc.text("TERMS & CONDITIONS", margin, y);
      y += 4.5;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(71, 85, 105);
      doc.text(challan.termsAndConditions, margin, y, { maxWidth: contentWidth });
      y += 10;
    }
  }

  // Footer / Signatory
  const footerY = pageHeight - 24;
  doc.setDrawColor(226, 232, 240);
  doc.line(margin, footerY, pageWidth - margin, footerY);

  doc.setFont("helvetica", "italic");
  doc.setFontSize(7.5);
  doc.setTextColor(148, 163, 184);
  doc.text("This is a computer-generated Delivery Challan and serves as proof of goods dispatch.", margin, footerY + 5);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(71, 85, 105);
  doc.text("Authorized Signatory", pageWidth - margin, footerY + 12, { align: "right" });

  return doc;
}

export async function downloadDeliveryChallanPDF(
  challan: DeliveryChallanDocument,
  customer?: CustomerOption | null,
) {
  const doc = await generateDeliveryChallanPDF(challan, customer);
  doc.save(`${challan.deliveryChallanNumber || "delivery-challan"}.pdf`);
}

export async function printDeliveryChallan(
  challan: DeliveryChallanDocument,
  customer?: CustomerOption | null,
) {
  const doc = await generateDeliveryChallanPDF(challan, customer);
  const blob = doc.output("blob");
  const blobUrl = URL.createObjectURL(blob);

  const iframe = document.createElement("iframe");
  iframe.style.position = "fixed";
  iframe.style.right = "0";
  iframe.style.bottom = "0";
  iframe.style.width = "0";
  iframe.style.height = "0";
  iframe.style.border = "none";
  document.body.appendChild(iframe);

  iframe.src = blobUrl;
  iframe.onload = () => {
    setTimeout(() => {
      iframe.focus();
      iframe.contentWindow?.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
        URL.revokeObjectURL(blobUrl);
      }, 2000);
    }, 200);
  };
}

