              <button
                type="button"
                onClick={() => {
                  onStatusChange(order.id, "Confirmed");
                  onClose();
                }}
                className="inline-flex items-center gap-1.5 rounded-xl bg-blue-600 px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-blue-700 transition cursor-pointer"
